"""MTL parser.

Secret: the concrete syntax of the DSL -- tokens, comments, how statements
are delimited (including multi-line continuation and `{ }` blocks), operator
precedence, the shapes of statements and declarations, and the structural
rules (exactly one aggregate, at most one group_by/window, unique aliases,
exactly one pipeline block when blocks are used).
"""

import re

from . import program as P
from .errors import DslError, TypeCheckError

_TRANSFORM_ARITY = {
    "len": (1, 1), "day": (1, 1), "month": (1, 1), "year": (1, 1), "round": (1, 2),
    "coalesce": (2, None), "lag": (1, 2), "lead": (1, 2),
    "starts_with": (2, 2), "ends_with": (2, 2), "contains": (2, 2),
}
_STRING_OPS = ("starts_with", "ends_with", "contains")
TYPE_NAMES = ("string", "int", "float", "bool", "timestamp")
AGGREGATE_FUNCTIONS = ("average", "median", "sum", "count", "std", "var", "min", "max")
_RESERVED_OUTPUT = ("window_start", "window_end")
_STAGES = (P.STAGE_PRE, P.STAGE_POST)
JOIN_TYPES = ("inner", "left", "right", "full")
_JOIN_CLAUSES = ("on", "within", "type", "project")
_DURATION_UNITS = ("s", "m", "h", "d")
WORKING_RELATION = "_"

_TOKEN_RE = re.compile(r"""
    (?P<ws>\s+)
  | (?P<float>(\d+\.\d*|\.\d+)([eE][+-]?\d+)?|\d+[eE][+-]?\d+)
  | (?P<int>\d+)
  | (?P<string>'[^'\n]*'|"[^"\n]*")
  | (?P<ident>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<op><=|>=|==|!=|[<>!&|()\[\],*+\-/%=:@.])
""", re.VERBOSE)


class _Token:
    __slots__ = ("kind", "text", "pos")

    def __init__(self, kind, text, pos):
        self.kind = kind
        self.text = text
        self.pos = pos

    def __repr__(self):
        return "%s %r" % (self.kind, self.text)


def _logical_lines(text):
    """Split source into statements, dropping comments and blank lines.

    A newline ends a statement unless it is inside brackets, the statement
    so far ends with a comma, or the next non-blank line starts with one.
    Outside brackets, '{' and '}' end the current statement and are yielded
    as statements of their own.  Yields (line_number, statement_text).
    """
    statements = []
    current = []
    start_line = None
    depth = 0
    line = 1
    i = 0
    n = len(text)

    def flush():
        stmt = "".join(current).strip()
        if stmt:
            statements.append((start_line, stmt))
        current.clear()

    while i < n:
        ch = text[i]
        if ch in "'\"":
            end = text.find(ch, i + 1)
            nl = text.find("\n", i + 1)
            if end == -1 or (nl != -1 and nl < end):
                raise DslError("line %d: unterminated string literal" % line)
            if start_line is None:
                start_line = line
            current.append(text[i:end + 1])
            i = end + 1
            continue
        if ch == "#":
            nl = text.find("\n", i)
            i = n if nl == -1 else nl
            continue
        if ch == "\r":
            i += 1
            continue
        if ch == "\n":
            line += 1
            i += 1
            so_far = "".join(current).strip()
            if not so_far:
                continue
            if depth > 0 or so_far.endswith(","):
                current.append(" ")
                continue
            if _next_significant_char(text, i) == ",":
                current.append(" ")
                continue
            flush()
            start_line = None
            depth = 0
            continue
        if ch in "{}" and depth <= 0:
            flush()
            statements.append((line, ch))
            start_line = None
            depth = 0
            i += 1
            continue
        if ch in "([":
            depth += 1
        elif ch in ")]":
            depth -= 1
        if start_line is None and not ch.isspace():
            start_line = line
        current.append(ch)
        i += 1
    flush()
    return statements


def _next_significant_char(text, i):
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
        elif ch == "#":
            nl = text.find("\n", i)
            if nl == -1:
                return None
            i = nl
        else:
            return ch
    return None


def _tokenize(stmt, line):
    tokens = []
    pos = 0
    while pos < len(stmt):
        m = _TOKEN_RE.match(stmt, pos)
        if not m:
            raise DslError("line %d: unexpected character %r" % (line, stmt[pos]))
        kind = m.lastgroup
        if kind != "ws":
            tokens.append(_Token(kind, m.group(), pos))
        pos = m.end()
    tokens.append(_Token("eof", "", pos))
    return tokens


class _StatementParser:
    def __init__(self, stmt, line):
        self.line = line
        self.stmt = stmt
        self.tokens = _tokenize(stmt, line)
        self.i = 0

    # -- token helpers -------------------------------------------------
    def peek(self, offset=0):
        return self.tokens[min(self.i + offset, len(self.tokens) - 1)]

    def advance(self):
        tok = self.tokens[self.i]
        if tok.kind != "eof":
            self.i += 1
        return tok

    def fail(self, message, tok=None):
        tok = tok or self.peek()
        where = "end of statement" if tok.kind == "eof" else repr(tok.text)
        raise DslError("line %d: %s (at %s)" % (self.line, message, where))

    def is_op(self, text):
        tok = self.peek()
        return tok.kind == "op" and tok.text == text

    def is_word(self, text):
        tok = self.peek()
        return tok.kind == "ident" and tok.text == text

    def expect_op(self, text):
        if not self.is_op(text):
            self.fail("expected %r" % text)
        return self.advance()

    def expect_word(self, text):
        if not self.is_word(text):
            self.fail("expected %r" % text)
        return self.advance()

    def expect_ident(self, what):
        tok = self.peek()
        if tok.kind != "ident":
            self.fail("expected %s" % what)
        return self.advance().text

    def expect_end(self):
        if self.peek().kind != "eof":
            self.fail("unexpected trailing input")

    def type_name(self):
        tok = self.peek()
        name = self.expect_ident("a type name")
        if name not in TYPE_NAMES:
            self.fail("unknown type %r" % name, tok)
        return name

    # -- block headers and declarations --------------------------------
    def schema_header(self):
        self.expect_word("schema")
        name = self.expect_ident("a schema name")
        base = None
        if self.is_word("extends"):
            self.advance()
            base = self.expect_ident("a base schema name")
            if self.is_op(","):
                self.fail("multiple inheritance is not allowed")
        self.expect_end()
        return name, base

    def pipeline_header(self):
        self.expect_word("pipeline")
        name = self.expect_ident("a pipeline name")
        schema = None
        if not self.is_op("{") and self.peek().kind != "eof":
            self.expect_word("using")
            schema = self.expect_ident("a schema name")
        self.expect_end()
        return name, schema

    # -- multi-source constructs ---------------------------------------
    def source_bindings(self):
        """name [as alias] {, name [as alias]}  (a trailing comma is allowed)"""
        bindings = []
        while self.peek().kind != "eof":
            name = self.expect_ident("a source name")
            alias = name
            if self.is_word("as"):
                self.advance()
                alias = self.expect_ident("a source alias")
            if alias == WORKING_RELATION:
                self.fail("%r is reserved for the working relation" % WORKING_RELATION)
            bindings.append(P.SourceBinding(name, alias))
            if not self.is_op(","):
                break
            self.advance()
        self.expect_end()
        return bindings

    def with_header(self):
        self.expect_word("with")
        alias = self.expect_ident("a source alias")
        self.expect_end()
        return alias

    def join_header(self):
        """join <left> with <right> on (<expr>) [within <duration>] [type <kind>] project"""
        self.expect_word("join")
        left = self.join_operand()
        self.expect_word("with")
        right = self.join_operand()
        on = within = kind = None
        while not self.is_word("project"):
            tok = self.peek()
            if tok.kind == "eof":
                raise DslError("line %d: join requires a project { ... } clause" % self.line)
            if self.is_word("on") and on is None:
                self.advance()
                on = self.expression()
            elif self.is_word("within") and within is None:
                self.advance()
                within = self.duration()
            elif self.is_word("type") and kind is None:
                self.advance()
                tok = self.peek()
                kind = self.expect_ident("a join type")
                if kind not in JOIN_TYPES:
                    self.fail("unknown join type %r (expected inner, left, right or full)"
                              % kind, tok)
            else:
                self.fail("expected on, within, type or project in join")
        self.advance()
        self.expect_end()
        if on is None:
            raise DslError("line %d: join requires an on (...) predicate" % self.line)
        return left, right, on, within, kind or "inner"

    def join_operand(self):
        return self.expect_ident("a source alias, join alias or _")

    def duration(self):
        if self.is_word("param") and self.peek(1).kind == "op" and self.peek(1).text == "(":
            self.advance()
            return P.Duration(None, None, self.param_ref().name)
        tok = self.peek()
        if tok.kind != "int":
            self.fail("expected a duration such as 10m")
        self.advance()
        amount = int(tok.text)
        unit_tok = self.peek()
        unit = self.expect_ident("a duration unit (s, m, h or d)")
        if unit not in _DURATION_UNITS:
            self.fail("unknown duration unit %r" % unit, unit_tok)
        if unit_tok.pos != tok.pos + len(tok.text):
            self.fail("expected a duration such as 10m", unit_tok)
        return P.Duration(amount, unit, None)

    def project_items(self):
        """<expr> [as <name>] {, ...}; a bare column reference keeps its column name."""
        items = []
        while self.peek().kind != "eof":
            start = self.peek()
            expr = self.expression()
            if self.is_word("as"):
                self.advance()
                tok = self.peek()
                if tok.kind == "string" and len(tok.text) > 2:
                    name = self.advance().text[1:-1]
                else:
                    name = self.expect_ident("a projected column name")
            elif isinstance(expr, P.ColumnRef):
                name = expr.name.rsplit(".", 1)[-1]
            else:
                self.fail("project entries need 'as <name>'", start)
            items.append(P.ProjectItem(expr, name))
            if not self.is_op(","):
                break
            self.advance()
        self.expect_end()
        return items

    def join_alias(self):
        self.expect_word("as")
        alias = self.expect_ident("a join alias")
        self.expect_end()
        return alias

    def field_list(self):
        """name: type [= expr] {, name: type [= expr]}"""
        fields = [self.field()]
        while self.is_op(","):
            self.advance()
            fields.append(self.field())
        self.expect_end()
        return fields

    def field(self):
        name = self.expect_ident("a field name")
        self.expect_op(":")
        value_type = self.type_name()
        expr = None
        if self.is_op("="):
            self.advance()
            expr = self.expression()
        return P.FieldDef(name, value_type, expr)

    def param_list(self):
        """name [: type] [= literal] {, ...}"""
        params = [self.param_decl()]
        while self.is_op(","):
            self.advance()
            params.append(self.param_decl())
        self.expect_end()
        return params

    def param_decl(self):
        name = self.expect_ident("a parameter name")
        value_type = default = None
        if self.is_op(":"):
            self.advance()
            value_type = self.type_name()
        if self.is_op("="):
            self.advance()
            default = self.literal()
        return P.ParamDef(name, value_type, default)

    def literal(self):
        sign = None
        if self.peek().kind == "op" and self.peek().text in ("-", "+"):
            sign = self.advance().text
        tok = self.peek()
        if tok.kind in ("int", "float"):
            self.advance()
            value = int(tok.text) if tok.kind == "int" else float(tok.text)
            return P.Literal(tok.kind, -value if sign == "-" else value)
        if sign is None:
            if tok.kind == "string":
                self.advance()
                return P.Literal("string", tok.text[1:-1])
            if tok.kind == "ident" and tok.text in ("true", "false"):
                self.advance()
                return P.Literal("bool", tok.text == "true")
        self.fail("expected a literal value")

    # -- statements ----------------------------------------------------
    def statement(self):
        keyword = self.peek()
        if keyword.kind != "ident":
            self.fail("expected a statement keyword")
        name = keyword.text
        if name == "filter":
            return self.filter_statement()
        if name == "apply":
            return self.apply_statement()
        if name == "group_by":
            return self.group_by_statement()
        if name == "window":
            return self.window_statement()
        if name == "aggregate":
            return self.aggregate_statement()
        if name == "calc":
            return self.calc_statement()
        self.fail("unknown statement %r" % name, keyword)

    def filter_statement(self):
        self.advance()
        self.expect_op("(")
        expr = self.expression()
        self.expect_op(")")
        self.expect_end()
        return P.Filter(expr)

    def apply_statement(self):
        self.advance()
        self.expect_op("(")
        expr = self.expression()
        self.expect_op(",")
        tok = self.peek()
        if tok.kind == "ident":
            column = self.advance().text
        elif tok.kind == "string" and len(tok.text) > 2:
            column = self.advance().text[1:-1]
        else:
            self.fail("expected a new column name")
        self.expect_op(")")
        self.expect_end()
        return P.Apply(expr, column)

    def group_by_statement(self):
        self.advance()
        self.expect_op("(")
        bracketed = self.is_op("[")
        if bracketed:
            self.advance()
        columns = [self.group_column()]
        while self.is_op(","):
            self.advance()
            columns.append(self.group_column())
        if bracketed:
            self.expect_op("]")
        self.expect_op(")")
        self.expect_end()
        if len(set(columns)) != len(columns):
            raise DslError("line %d: duplicate column in group_by" % self.line)
        return P.GroupBy(tuple(columns))

    def group_column(self):
        tok = self.peek()
        if tok.kind == "string" and len(tok.text) > 2:
            return self.advance().text[1:-1]
        return self.expect_ident("a column name")

    def window_statement(self):
        m = re.match(r"^window\s*\(\s*(\d+)([mhd])\s*\)$", self.stmt)
        if m:
            amount = int(m.group(1))
            if amount <= 0:
                raise DslError("line %d: window duration must be positive" % self.line)
            return P.Window(amount, m.group(2))
        self.advance()
        self.expect_op("(")
        if self.is_word("param") and self.peek(1).kind == "op" and self.peek(1).text == "(":
            self.advance()
            ref = self.param_ref()
            self.expect_op(")")
            self.expect_end()
            return P.Window(None, None, ref.name)
        raise DslError("line %d: invalid window statement, expected window(<n><m|h|d>)"
                       % self.line)

    def aggregate_statement(self):
        self.advance()
        items = [self.aggregate_item()]
        while self.is_op(","):
            self.advance()
            items.append(self.aggregate_item())
        self.expect_end()
        aliases = [it.alias for it in items]
        if len(set(aliases)) != len(aliases):
            raise DslError("line %d: aggregate aliases must be unique" % self.line)
        return P.Aggregate(tuple(items))

    def aggregate_item(self):
        fn_tok = self.peek()
        fn = self.expect_ident("an aggregate function")
        if fn not in AGGREGATE_FUNCTIONS:
            self.fail("unknown aggregate function %r" % fn, fn_tok)
        self.expect_op("(")
        if self.is_op("*"):
            self.advance()
            column = None
        else:
            column = self.expect_ident("a column name or *")
        self.expect_op(")")
        self.expect_word("as")
        alias = self.expect_ident("an alias")
        return P.AggregateItem(fn, column, alias)

    def calc_statement(self):
        """calc name = expr : type [@stage(pre|post_agg)]  (or calc name: type = expr ...)"""
        self.advance()
        name = self.expect_ident("a calculated field name")
        if self.is_op(":"):
            self.advance()
            value_type = self.type_name()
            self.expect_op("=")
            expr = self.expression()
        else:
            self.expect_op("=")
            expr = self.expression()
            self.expect_op(":")
            value_type = self.type_name()
        stage = P.STAGE_PRE
        if self.is_op("@"):
            self.advance()
            self.expect_word("stage")
            self.expect_op("(")
            tok = self.peek()
            stage = self.expect_ident("a stage name")
            if stage not in _STAGES:
                self.fail("unknown stage %r (expected pre or post_agg)" % stage, tok)
            self.expect_op(")")
        self.expect_end()
        return P.Calc(name, expr, value_type, stage)

    # -- expressions ---------------------------------------------------
    def expression(self):
        return self.or_expr()

    def or_expr(self):
        left = self.and_expr()
        while self.is_op("|"):
            self.advance()
            left = P.Binary("|", left, self.and_expr())
        return left

    def and_expr(self):
        left = self.not_expr()
        while self.is_op("&"):
            self.advance()
            left = P.Binary("&", left, self.not_expr())
        return left

    def not_expr(self):
        if self.is_op("!"):
            self.advance()
            return P.Unary("!", self.not_expr())
        return self.comparison()

    def comparison(self):
        left = self.additive()
        tok = self.peek()
        if tok.kind == "op" and tok.text in ("<", "<=", ">", ">=", "==", "!="):
            op = self.advance().text
            right = self.additive()
            self.reject_chain()
            return P.Binary(op, left, right)
        if tok.kind == "ident" and tok.text == "in":
            self.advance()
            right = self.additive()
            self.reject_chain()
            return P.Binary("in", left, right)
        if tok.kind == "ident" and tok.text in _STRING_OPS:
            op = self.advance().text
            right = self.additive()
            self.reject_chain()
            return P.Call(op, (left, right))
        return left

    def reject_chain(self):
        tok = self.peek()
        if (tok.kind == "op" and tok.text in ("<", "<=", ">", ">=", "==", "!=")) or \
                (tok.kind == "ident" and tok.text in ("in",) + _STRING_OPS):
            self.fail("comparisons cannot be chained")

    def additive(self):
        left = self.term()
        while self.peek().kind == "op" and self.peek().text in ("+", "-"):
            op = self.advance().text
            left = P.Binary(op, left, self.term())
        return left

    def term(self):
        left = self.unary()
        while self.peek().kind == "op" and self.peek().text in ("*", "/", "%"):
            op = self.advance().text
            left = P.Binary(op, left, self.unary())
        return left

    def unary(self):
        if self.peek().kind == "op" and self.peek().text in ("-", "+"):
            op = self.advance().text
            return P.Unary(op, self.unary())
        return self.primary()

    def primary(self):
        tok = self.peek()
        if tok.kind == "int":
            self.advance()
            return P.Literal("int", int(tok.text))
        if tok.kind == "float":
            self.advance()
            return P.Literal("float", float(tok.text))
        if tok.kind == "string":
            self.advance()
            return P.Literal("string", tok.text[1:-1])
        if tok.kind == "ident":
            if tok.text in ("true", "false"):
                self.advance()
                return P.Literal("bool", tok.text == "true")
            if tok.text in ("in", "as"):
                self.fail("unexpected keyword")
            self.advance()
            if self.is_op(".") and self.peek(1).kind == "ident":
                self.advance()
                return P.ColumnRef("%s.%s" % (tok.text, self.advance().text))
            if self.is_op("("):
                if tok.text == "param":
                    return self.param_ref()
                if tok.text == "cast":
                    return self.cast()
                return self.call(tok)
            return P.ColumnRef(tok.text)
        if self.is_op("("):
            self.advance()
            inner = self.expression()
            self.expect_op(")")
            return inner
        self.fail("expected an expression")

    def param_ref(self):
        self.expect_op("(")
        tok = self.peek()
        if tok.kind != "string" or len(tok.text) <= 2:
            self.fail("param() expects a quoted parameter name")
        self.advance()
        self.expect_op(")")
        return P.Param(tok.text[1:-1])

    def cast(self):
        self.expect_op("(")
        inner = self.expression()
        self.expect_word("as")
        value_type = self.type_name()
        self.expect_op(")")
        return P.Cast(inner, value_type)

    def call(self, tok):
        self.expect_op("(")
        args = []
        if not self.is_op(")"):
            args.append(self.expression())
            while self.is_op(","):
                self.advance()
                args.append(self.expression())
        self.expect_op(")")
        if tok.text not in _TRANSFORM_ARITY:
            self.fail("unknown function %r" % tok.text, tok)
        low, high = _TRANSFORM_ARITY[tok.text]
        if len(args) < low or (high is not None and len(args) > high):
            self.fail("wrong number of arguments to %s()" % tok.text, tok)
        return P.Call(tok.text, tuple(args))


def _first_word(stmt):
    m = re.match(r"[A-Za-z_][A-Za-z0-9_]*", stmt)
    return m.group() if m else None


def parse_program(text):
    """Parse DSL source into a program.Program; raises DslError."""
    statements = _logical_lines(text)
    if any(stmt in ("{", "}") or _first_word(stmt) in ("schema", "pipeline")
           for _, stmt in statements):
        return _parse_blocks(statements)
    return _build_program(statements)


def _build_program(statements, **extra):
    steps = []
    calcs = []
    group_by = window = aggregate = None
    for line, stmt in statements:
        node = _StatementParser(stmt, line).statement()
        if isinstance(node, (P.Filter, P.Apply)):
            steps.append(node)
        elif isinstance(node, P.Calc):
            calcs.append(node)
        elif isinstance(node, P.GroupBy):
            if group_by is not None:
                raise DslError("line %d: group_by may appear at most once" % line)
            group_by = node
        elif isinstance(node, P.Window):
            if window is not None:
                raise DslError("line %d: window may appear at most once" % line)
            window = node
        else:
            if aggregate is not None:
                raise DslError("line %d: aggregate must appear exactly once" % line)
            aggregate = node
    if aggregate is None:
        raise DslError("program has no aggregate statement")
    _check_calc_names(calcs)
    _check_output_names(group_by, window, aggregate, calcs)
    return P.Program(steps, group_by, window, aggregate, calcs=calcs, **extra)


class _Cursor:
    def __init__(self, statements):
        self.statements = statements
        self.i = 0

    def done(self):
        return self.i >= len(self.statements)

    def next(self, what):
        if self.done():
            raise DslError("unexpected end of DSL: expected %s" % what)
        item = self.statements[self.i]
        self.i += 1
        return item

    def expect_open(self, what):
        line, stmt = self.next("'{' after %s header" % what)
        if stmt != "{":
            raise DslError("line %d: expected '{' after %s header" % (line, what))

    def block(self, what):
        """Yield (line, stmt) up to the closing brace of the current block."""
        while True:
            line, stmt = self.next("'}' closing %s block" % what)
            if stmt == "}":
                return
            if stmt == "{":
                raise DslError("line %d: unexpected '{' in %s block" % (line, what))
            yield line, stmt


def _parse_blocks(statements):
    cursor = _Cursor(statements)
    schemas = {}
    pipeline = None
    while not cursor.done():
        line, stmt = cursor.next("a block")
        word = _first_word(stmt)
        if word == "schema":
            name, base = _StatementParser(stmt, line).schema_header()
            if name in schemas:
                raise DslError("line %d: schema %r is defined more than once" % (line, name))
            cursor.expect_open("schema")
            fields = []
            seen = set()
            for fline, fstmt in cursor.block("schema"):
                for field in _StatementParser(fstmt, fline).field_list():
                    if field.name in seen:
                        raise DslError("line %d: field %r declared twice in schema %r"
                                       % (fline, field.name, name))
                    seen.add(field.name)
                    fields.append(field)
            schemas[name] = P.SchemaDef(name, base, tuple(fields))
        elif word == "pipeline":
            if pipeline is not None:
                raise DslError("line %d: only one pipeline block is allowed" % line)
            pipeline = (line,) + _StatementParser(stmt, line).pipeline_header()
            cursor.expect_open("pipeline")
            pipeline += _pipeline_body(cursor)
        else:
            raise DslError("line %d: expected a schema or pipeline block" % line)
    if pipeline is None:
        raise DslError("DSL has no pipeline block")
    line, name, schema_name, body, params, sources, scoped, joins = pipeline
    if schema_name is None:
        if sources is None:
            raise DslError("line %d: pipeline requires 'using <schema>'" % line)
    elif schema_name not in schemas:
        raise DslError("line %d: pipeline uses unknown schema %r" % (line, schema_name))
    _check_sources(sources, scoped, joins)
    return _build_program(body, params=params, schemas=schemas,
                          schema_name=schema_name, name=name, sources=sources,
                          scoped=scoped, joins=joins)


def _pipeline_body(cursor):
    body = []
    params = None
    sources = None
    scoped = []
    joins = []
    started = False
    while True:
        line, stmt = cursor.next("'}' closing pipeline block")
        if stmt == "}":
            break
        if stmt == "{":
            raise DslError("line %d: unexpected '{' in pipeline block" % line)
        word = _first_word(stmt)
        if word == "sources" and stmt.strip() == "sources":
            if sources is not None:
                raise DslError("line %d: sources block may appear at most once" % line)
            if started:
                raise DslError("line %d: sources block must precede all other statements"
                               % line)
            cursor.expect_open("sources")
            sources = []
            for bline, bstmt in cursor.block("sources"):
                sources.extend(_StatementParser(bstmt, bline).source_bindings())
            if not sources:
                raise DslError("line %d: sources block binds no source" % line)
            started = True
            continue
        if word == "with":
            scoped.append(_scoped_block(cursor, line, stmt))
            started = True
            continue
        if word == "join":
            joins.append(_join(cursor, line, stmt))
            started = True
            continue
        if word == "params" and stmt.strip() == "params":
            if params is not None:
                raise DslError("line %d: params block may appear at most once" % line)
            cursor.expect_open("params")
            params = []
            seen = set()
            for pline, pstmt in cursor.block("params"):
                for decl in _StatementParser(pstmt, pline).param_list():
                    if decl.name in seen:
                        raise DslError("line %d: parameter %r declared twice"
                                       % (pline, decl.name))
                    seen.add(decl.name)
                    params.append(decl)
        else:
            body.append((line, stmt))
            started = True
    return body, tuple(params or ()), sources, scoped, joins


def _scoped_block(cursor, line, stmt):
    alias = _StatementParser(stmt, line).with_header()
    cursor.expect_open("with")
    steps = []
    for sline, sstmt in cursor.block("with"):
        node = _StatementParser(sstmt, sline).statement()
        if isinstance(node, (P.GroupBy, P.Window, P.Aggregate)):
            raise DslError("line %d: with %s { } accepts only pre-stage calcs and filters"
                           % (sline, alias))
        if isinstance(node, P.Calc) and node.stage != P.STAGE_PRE:
            raise TypeCheckError("line %d: calc %r: @stage(%s) is not allowed inside with %s { }"
                                 % (sline, node.name, node.stage, alias))
        steps.append(node)
    return P.ScopedBlock(alias, tuple(steps), line)


def _join(cursor, line, stmt):
    parts = [stmt]
    while not re.search(r"\bproject\s*$", parts[-1]) and not cursor.done():
        nstmt = cursor.statements[cursor.i][1]
        if _first_word(nstmt) not in _JOIN_CLAUSES:
            break
        cursor.i += 1
        parts.append(nstmt)
    header = " ".join(parts)
    left, right, on, within, kind = _StatementParser(header, line).join_header()
    if cursor.done() or cursor.statements[cursor.i][1] != "{":
        raise DslError("line %d: expected '{' after project" % line)
    cursor.i += 1
    items = []
    for pline, pstmt in cursor.block("project"):
        items.extend(_StatementParser(pstmt, pline).project_items())
    if not items:
        raise DslError("line %d: project { } must define at least one column" % line)
    names = [item.name for item in items]
    for name in names:
        if names.count(name) > 1:
            raise DslError("line %d: column %r appears more than once in project; "
                           "disambiguate it with 'as'" % (line, name))
    alias = None
    if not cursor.done() and _first_word(cursor.statements[cursor.i][1]) == "as":
        aline, astmt = cursor.next("a join alias")
        alias = _StatementParser(astmt, aline).join_alias()
    return P.Join(left, right, on, within, kind, tuple(items), alias, line)


def _check_sources(sources, scoped, joins):
    if sources is None:
        if joins:
            raise DslError("line %d: join requires a sources { } block" % joins[0].line)
        if scoped:
            raise DslError("line %d: with blocks require a sources { } block" % scoped[0].line)
        return
    aliases = set()
    for binding in sources:
        if binding.alias in aliases:
            raise DslError("source alias %r is bound more than once" % binding.alias)
        aliases.add(binding.alias)
    if not joins:
        raise DslError("pipeline declares sources but no join combines them")
    for block in scoped:
        if block.alias not in aliases:
            raise DslError("line %d: with refers to unknown source alias %r"
                           % (block.line, block.alias))
    known = set(aliases)
    for index, join in enumerate(joins):
        for operand in (join.left, join.right):
            if operand == WORKING_RELATION:
                if index == 0:
                    raise DslError("line %d: '_' refers to the previous join, but this is the "
                                   "first join" % join.line)
            elif operand not in known:
                raise DslError("line %d: join refers to unknown alias %r" % (join.line, operand))
        if join.left == join.right:
            raise DslError("line %d: cannot join %r with itself; bind the source twice under "
                           "different aliases" % (join.line, join.left))
        if join.alias is not None:
            if join.alias in known or join.alias == WORKING_RELATION:
                raise DslError("line %d: join alias %r is already in use"
                               % (join.line, join.alias))
            known.add(join.alias)


def _check_calc_names(calcs):
    seen = set()
    for calc in calcs:
        if calc.name in seen:
            raise DslError("calculated field %r is declared more than once" % calc.name)
        seen.add(calc.name)


def _check_output_names(group_by, window, aggregate, calcs):
    taken = set(group_by.columns) if group_by else set()
    if window:
        clash = taken.intersection(_RESERVED_OUTPUT)
        if clash:
            raise DslError("group_by column %r collides with a window field" % sorted(clash)[0])
        taken.update(_RESERVED_OUTPUT)
    for item in aggregate.items:
        if item.alias in taken:
            raise DslError("aggregate alias %r collides with another output field" % item.alias)
        taken.add(item.alias)
    for calc in calcs:
        if calc.stage == P.STAGE_POST and calc.name in taken:
            raise DslError("calculated field %r collides with another output field" % calc.name)

content.content:
"""Pipeline execution.

Secret: the execution strategy -- schema-level and @stage(pre) calculated
fields materialise first, row steps then run in program order, rollup
clauses act on the final rows, result rows are put in their canonical order
and @stage(post_agg) calcs are evaluated over that order; everything is
type-checked before any row is touched; rows are bucketed by (window, group
key).
"""

import re
from collections import namedtuple

from . import program as P
from . import valuetypes as T
from .aggregates import make_aggregate, result_type
from . import quality as Q
from .errors import DslError, ExecutionError, TypeCheckError
from .expressions import coerce, column_references, compile_expression, is_assignable
from .quality import BadRecord, BadRecordLog, Provenance
from .windowing import TumblingWindow

ResultRow = namedtuple("ResultRow", "window_start window_end keys values")
_WINDOW_FIELDS = ("window_start", "window_end")


class ResultSet:
    """Rollup outcome handed to the renderer.

    windowed:      whether rows carry window bounds
    group_columns: group_by column names, in declared order (may be empty)
    group_types:   the value type of each group column
    aliases:       aggregate aliases
    scalar:        True when there is neither window nor group_by
    rows:          ResultRow list in output order (keys align with
                   group_columns, values by alias and calc name)
    calc_names:    post-aggregation calc names
    calc_types:    the value type of each post-aggregation calc
    """

    def __init__(self, windowed, group_columns, group_types, aliases, scalar, rows,
                 calc_names=(), calc_types=()):
        self.windowed = windowed
        self.group_columns = tuple(group_columns)
        self.group_types = tuple(group_types)
        self.aliases = tuple(aliases)
        self.scalar = scalar
        self.rows = rows
        self.calc_names = tuple(calc_names)
        self.calc_types = tuple(calc_types)


class _Schema:
    """Static view of column types as the program evolves them."""

    def __init__(self, base):
        self._base = base
        self._overrides = {}

    def has(self, name):
        return name in self._overrides or self._base.has(name)

    def type_of(self, name):
        if name in self._overrides:
            return self._overrides[name]
        return self._base.type_of(name)

    def define(self, name, value_type):
        self._overrides[name] = value_type


class _Names:
    """A plain name -> type mapping with the has/type_of protocol."""

    def __init__(self):
        self._types = {}

    def has(self, name):
        return name in self._types

    def type_of(self, name):
        return self._types[name]

    def define(self, name, value_type):
        self._types[name] = value_type


class _RowRecord:
    """One input row as seen by row-level expressions."""

    __slots__ = ("data",)

    def __init__(self, data):
        self.data = data

    def get(self, name):
        return self.data[name]


class _OutputRecord:
    """One result row as seen by post-aggregation calcs."""

    __slots__ = ("data", "position", "table")

    def __init__(self, data, position, table):
        self.data = data
        self.position = position
        self.table = table

    def get(self, name):
        return self.data[name]


def _require_column(schema, name, context):
    if not schema.has(name):
        raise TypeCheckError("unknown column %r in %s" % (name, context))
    return schema.type_of(name)


def _sort_key(value):
    # Nulls sort first; values within one column share a type, so Python's
    # ordering gives numeric, code-point and chronological order respectively.
    return (0, 0) if value is None else (1, value)


def _check_declared(name, declared, compiled, what):
    if not is_assignable(declared, compiled.type):
        raise TypeCheckError("%s %r is declared %s but its expression is %s"
                             % (what, name, T.type_name(declared), T.type_name(compiled.type)))
    return coerce(declared, compiled)


def _window(program, params):
    spec = program.window
    if spec.param is None:
        return TumblingWindow(spec.amount, spec.unit)
    if spec.param not in params:
        raise DslError("unknown parameter %r" % spec.param)
    value_type, value = params[spec.param]
    m = re.match(r"^\s*(\d+)\s*([mhd])\s*$", value) if T.is_string(value_type) else None
    if not m or int(m.group(1)) <= 0:
        raise TypeCheckError("window parameter %r must be a duration like '1h', got %r"
                             % (spec.param, value))
    return TumblingWindow(int(m.group(1)), m.group(2))


def execute(program, dataset, schema_def=None, params=None, ts_parser=None, bad_records=None):
    params = params or {}
    schema = _Schema(dataset)
    row_ops = []

    def compile_for_rows(expr, unknown=None):
        return compile_expression(expr, schema, params, unknown=unknown, ts_parser=ts_parser)

    # Schema-level calculated fields.
    if schema_def is not None:
        def schema_unknown(name):
            return DslError("schema field references unknown field %r" % name)
        for field in schema_def.calcs:
            compiled = compile_for_rows(field.expression, schema_unknown)
            evaluate = _check_declared(field.name, field.type, compiled, "schema field")
            schema.define(field.name, field.type)
            row_ops.append(("derive", field.name, field.type, evaluate))

    # @stage(pre) calcs.
    aliases = [item.alias for item in program.aggregate.items]
    pre_names = [c.name for c in program.pre_calcs]
    post_names = [c.name for c in program.post_calcs]
    apply_targets = {s.column for s in program.steps if isinstance(s, P.Apply)}
    for index, calc in enumerate(program.pre_calcs):
        if schema.has(calc.name) or calc.name in apply_targets:
            raise DslError("calculated field %r collides with an existing field" % calc.name)
        later = set(pre_names[index + 1:])

        def pre_unknown(name, later=later):
            if name in aliases or name in post_names:
                return DslError("@stage(pre) calc cannot use aggregate output %r" % name)
            if name in later:
                return DslError("calc references %r before it is declared" % name)
            return TypeCheckError("unknown column %r" % name)
        compiled = compile_for_rows(calc.expression, pre_unknown)
        evaluate = _check_declared(calc.name, calc.type, compiled, "calc")
        schema.define(calc.name, calc.type)
        row_ops.append(("derive", calc.name, calc.type, evaluate))

    # Part 1 row steps.
    for step in program.steps:
        if isinstance(step, P.Filter):
            compiled = compile_for_rows(step.predicate)
            if not T.is_bool(compiled.type):
                raise TypeCheckError("filter expression must be boolean, got %s"
                                     % T.type_name(compiled.type))
            row_ops.append(("filter", compiled.evaluate))
        else:
            compiled = compile_for_rows(step.expression)
            schema.define(step.column, compiled.type)
            row_ops.append(("derive", step.column, compiled.type, compiled.evaluate))

    group_columns = program.group_by.columns if program.group_by else ()
    group_types = [_require_column(schema, c, "group_by") for c in group_columns]

    window = None
    if program.window is not None:
        ts_type = _require_column(schema, "timestamp", "window")
        if not T.is_timestamp(ts_type):
            raise TypeCheckError("window requires 'timestamp' to be a timestamp, got %s"
                                 % T.type_name(ts_type))
        window = _window(program, params)

    aggregates = []
    output_names = _Names()
    if window is not None:
        for name in _WINDOW_FIELDS:
            output_names.define(name, T.TIMESTAMP)
    for name, value_type in zip(group_columns, group_types):
        output_names.define(name, value_type)
    for item in program.aggregate.items:
        input_type = None
        if item.column is not None:
            input_type = _require_column(schema, item.column, "aggregate")
        aggregates.append((item, make_aggregate(item.function, input_type)))
        output_names.define(item.alias, result_type(item.function, input_type))

    # @stage(post_agg) calcs.
    post_calcs = []
    for index, calc in enumerate(program.post_calcs):
        if output_names.has(calc.name):
            raise DslError("calculated field %r collides with another output field" % calc.name)
        later = set(post_names[index + 1:])

        def post_unknown(name, later=later):
            if name in later:
                return DslError("calc references %r before it is declared" % name)
            return TypeCheckError("@stage(post_agg) calc references %r, which is not a "
                                  "group key, window bound, aggregate or earlier calc" % name)
        compiled = compile_expression(calc.expression, output_names, params, row_relative=True,
                                      unknown=post_unknown, ts_parser=ts_parser)
        evaluate = _check_declared(calc.name, calc.type, compiled, "calc")
        output_names.define(calc.name, calc.type)
        post_calcs.append((calc.name, evaluate))

    referenced = _referenced_columns(program, schema_def, group_columns, window is not None)
    buckets = _evaluate_rows(dataset, row_ops, window, group_columns, referenced,
                             bad_records if bad_records is not None else BadRecordLog(False))

    scalar = window is None and not group_columns
    if scalar and not buckets:
        buckets[((None, None), ())] = []

    rows = []
    for (bounds, keys), records in buckets.items():
        values = {}
        for item, aggregate in aggregates:
            if item.column is None:
                inputs = [True] * len(records)
            else:
                inputs = [r[item.column] for r in records]
            values[item.alias] = aggregate.compute(inputs)
        rows.append(ResultRow(bounds[0], bounds[1], keys, values))
    rows.sort(key=lambda r: (_sort_key(r.window_start), tuple(_sort_key(k) for k in r.keys)))

    if post_calcs:
        table = []
        for position, row in enumerate(rows):
            data = dict(row.values)
            data.update(zip(group_columns, row.keys))
            if window is not None:
                data["window_start"] = row.window_start
                data["window_end"] = row.window_end
            table.append(_OutputRecord(data, position, table))
        for name, evaluate in post_calcs:
            for record in table:
                record.data[name] = evaluate(record)
        for row, record in zip(rows, table):
            for name, _ in post_calcs:
                row.values[name] = record.data[name]

    post = program.post_calcs
    return ResultSet(window is not None, group_columns, group_types, aliases, scalar, rows,
                     [c.name for c in post], [c.type for c in post])


def _referenced_columns(program, schema_def, group_columns, windowed):
    """Input columns the pipeline reads (directly or via schema calcs)."""
    names = set(group_columns)
    exprs = [c.expression for c in program.pre_calcs]
    if schema_def is not None:
        exprs.extend(f.expression for f in schema_def.calcs)
    for step in program.steps:
        exprs.append(step.predicate if isinstance(step, P.Filter) else step.expression)
    for expr in exprs:
        names.update(column_references(expr))
    names.update(item.column for item in program.aggregate.items if item.column is not None)
    if windowed:
        names.add("timestamp")
    return names


def _apply_row_ops(row_ops, record):
    """Run the row steps on one record; False if a filter drops it."""
    data = record.data
    for op in row_ops:
        if op[0] == "filter":
            if op[1](record) is not True:
                return False
        else:
            data[op[1]] = op[3](record)
    return True


def _evaluate_rows(dataset, row_ops, window, group_columns, referenced, log):
    """Evaluate row steps row by row and bucket the surviving rows by (window, keys)."""
    buckets = {}
    for entry in dataset.entries():
        tag = entry[0]
        if tag == "absent":
            missing = [n for n in entry[2] if n in referenced]
            if missing and log.strict:
                log.add(BadRecord(Provenance(entry[1], None, None), Q.MISSING_REQUIRED_FIELD,
                                  "input lacks column(s) %s" % ", ".join(missing),
                                  {"columns": missing}))
            continue
        if tag == "bad":
            log.add(entry[1])
            continue
        prov, data = entry[1], entry[2]
        failure = None
        try:
            keep = _apply_row_ops(row_ops, _RowRecord(data))
        except TypeCheckError as exc:
            failure = (Q.TYPE_ERROR, str(exc))
        except ExecutionError as exc:
            failure = (Q.RUNTIME_ERROR, str(exc))
        except (ArithmeticError, ValueError) as exc:
            failure = (Q.RUNTIME_ERROR, "evaluation failed: %s" % exc)
        if failure is not None:
            log.add(BadRecord(prov, failure[0], failure[1], {"values": data}))
            continue
        if not keep:
            continue
        bounds = (None, None)
        if window is not None:
            instant = data.get("timestamp")
            if instant is None:
                log.add(BadRecord(prov, Q.MISSING_REQUIRED_FIELD,
                                  "timestamp is null; the row cannot be assigned to a window",
                                  {"column": "timestamp", "values": data}))
                continue
            try:
                bounds = window.bounds(instant)
            except ExecutionError as exc:
                log.add(BadRecord(prov, Q.RUNTIME_ERROR, str(exc), {"values": data}))
                continue
        key = (bounds, tuple(data[c] for c in group_columns))
        buckets.setdefault(key, []).append(data)
    return buckets

tool_use_result.stdout:
"""Pipeline execution.

Secret: the execution strategy -- schema-level and @stage(pre) calculated
fields materialise first, row steps then run in program order, rollup
clauses act on the final rows, result rows are put in their canonical order
and @stage(post_agg) calcs are evaluated over that order; everything is
type-checked before any row is touched; rows are bucketed by (window, group
key).
"""

import re
from collections import namedtuple

from . import program as P
from . import valuetypes as T
from .aggregates import make_aggregate, result_type
from . import quality as Q
from .errors import DslError, ExecutionError, TypeCheckError
from .expressions import coerce, column_references, compile_expression, is_assignable
from .quality import BadRecord, BadRecordLog, Provenance
from .windowing import TumblingWindow

ResultRow = namedtuple("ResultRow", "window_start window_end keys values")
_WINDOW_FIELDS = ("window_start", "window_end")


class ResultSet:
    """Rollup outcome handed to the renderer.

    windowed:      whether rows carry window bounds
    group_columns: group_by column names, in declared order (may be empty)
    group_types:   the value type of each group column
    aliases:       aggregate aliases
    scalar:        True when there is neither window nor group_by
    rows:          ResultRow list in output order (keys align with
                   group_columns, values by alias and calc name)
    calc_names:    post-aggregation calc names
    calc_types:    the value type of each post-aggregation calc
    """

    def __init__(self, windowed, group_columns, group_types, aliases, scalar, rows,
                 calc_names=(), calc_types=()):
        self.windowed = windowed
        self.group_columns = tuple(group_columns)
        self.group_types = tuple(group_types)
        self.aliases = tuple(aliases)
        self.scalar = scalar
        self.rows = rows
        self.calc_names = tuple(calc_names)
        self.calc_types = tuple(calc_types)


class _Schema:
    """Static view of column types as the program evolves them."""

    def __init__(self, base):
        self._base = base
        self._overrides = {}

    def has(self, name):
        return name in self._overrides or self._base.has(name)

    def type_of(self, name):
        if name in self._overrides:
            return self._overrides[name]
        return self._base.type_of(name)

    def define(self, name, value_type):
        self._overrides[name] = value_type


class _Names:
    """A plain name -> type mapping with the has/type_of protocol."""

    def __init__(self):
        self._types = {}

    def has(self, name):
        return name in self._types

    def type_of(self, name):
        return self._types[name]

    def define(self, name, value_type):
        self._types[name] = value_type


class _RowRecord:
    """One input row as seen by row-level expressions."""

    __slots__ = ("data",)

    def __init__(self, data):
        self.data = data

    def get(self, name):
        return self.data[name]


class _OutputRecord:
    """One result row as seen by post-aggregation calcs."""

    __slots__ = ("data", "position", "table")

    def __init__(self, data, position, table):
        self.data = data
        self.position = position
        self.table = table

    def get(self, name):
        return self.data[name]


def _require_column(schema, name, context):
    if not schema.has(name):
        raise TypeCheckError("unknown column %r in %s" % (name, context))
    return schema.type_of(name)


def _sort_key(value):
    # Nulls sort first; values within one column share a type, so Python's
    # ordering gives numeric, code-point and chronological order respectively.
    return (0, 0) if value is None else (1, value)


def _check_declared(name, declared, compiled, what):
    if not is_assignable(declared, compiled.type):
        raise TypeCheckError("%s %r is declared %s but its expression is %s"
                             % (what, name, T.type_name(declared), T.type_name(compiled.type)))
    return coerce(declared, compiled)


def _window(program, params):
    spec = program.window
    if spec.param is None:
        return TumblingWindow(spec.amount, spec.unit)
    if spec.param not in params:
        raise DslError("unknown parameter %r" % spec.param)
    value_type, value = params[spec.param]
    m = re.match(r"^\s*(\d+)\s*([mhd])\s*$", value) if T.is_string(value_type) else None
    if not m or int(m.group(1)) <= 0:
        raise TypeCheckError("window parameter %r must be a duration like '1h', got %r"
                             % (spec.param, value))
    return TumblingWindow(int(m.group(1)), m.group(2))


def execute(program, dataset, schema_def=None, params=None, ts_parser=None, bad_records=None):
    params = params or {}
    schema = _Schema(dataset)
    row_ops = []

    def compile_for_rows(expr, unknown=None):
        return compile_expression(expr, schema, params, unknown=unknown, ts_parser=ts_parser)

    # Schema-level calculated fields.
    if schema_def is not None:
        def schema_unknown(name):
            return DslError("schema field references unknown field %r" % name)
        for field in schema_def.calcs:
            compiled = compile_for_rows(field.expression, schema_unknown)
            evaluate = _check_declared(field.name, field.type, compiled, "schema field")
            schema.define(field.name, field.type)
            row_ops.append(("derive", field.name, field.type, evaluate))

    # @stage(pre) calcs.
    aliases = [item.alias for item in program.aggregate.items]
    pre_names = [c.name for c in program.pre_calcs]
    post_names = [c.name for c in program.post_calcs]
    apply_targets = {s.column for s in program.steps if isinstance(s, P.Apply)}
    for index, calc in enumerate(program.pre_calcs):
        if schema.has(calc.name) or calc.name in apply_targets:
            raise DslError("calculated field %r collides with an existing field" % calc.name)
        later = set(pre_names[index + 1:])

        def pre_unknown(name, later=later):
            if name in aliases or name in post_names:
                return DslError("@stage(pre) calc cannot use aggregate output %r" % name)
            if name in later:
                return DslError("calc references %r before it is declared" % name)
            return TypeCheckError("unknown column %r" % name)
        compiled = compile_for_rows(calc.expression, pre_unknown)
        evaluate = _check_declared(calc.name, calc.type, compiled, "calc")
        schema.define(calc.name, calc.type)
        row_ops.append(("derive", calc.name, calc.type, evaluate))

    # Part 1 row steps.
    for step in program.steps:
        if isinstance(step, P.Filter):
            compiled = compile_for_rows(step.predicate)
            if not T.is_bool(compiled.type):
                raise TypeCheckError("filter expression must be boolean, got %s"
                                     % T.type_name(compiled.type))
            row_ops.append(("filter", compiled.evaluate))
        else:
            compiled = compile_for_rows(step.expression)
            schema.define(step.column, compiled.type)
            row_ops.append(("derive", step.column, compiled.type, compiled.evaluate))

    group_columns = program.group_by.columns if program.group_by else ()
    group_types = [_require_column(schema, c, "group_by") for c in group_columns]

    window = None
    if program.window is not None:
        ts_type = _require_column(schema, "timestamp", "window")
        if not T.is_timestamp(ts_type):
            raise TypeCheckError("window requires 'timestamp' to be a timestamp, got %s"
                                 % T.type_name(ts_type))
        window = _window(program, params)

    aggregates = []
    output_names = _Names()
    if window is not None:
        for name in _WINDOW_FIELDS:
            output_names.define(name, T.TIMESTAMP)
    for name, value_type in zip(group_columns, group_types):
        output_names.define(name, value_type)
    for item in program.aggregate.items:
        input_type = None
        if item.column is not None:
            input_type = _require_column(schema, item.column, "aggregate")
        aggregates.append((item, make_aggregate(item.function, input_type)))
        output_names.define(item.alias, result_type(item.function, input_type))

    # @stage(post_agg) calcs.
    post_calcs = []
    for index, calc in enumerate(program.post_calcs):
        if output_names.has(calc.name):
            raise DslError("calculated field %r collides with another output field" % calc.name)
        later = set(post_names[index + 1:])

        def post_unknown(name, later=later):
            if name in later:
                return DslError("calc references %r before it is declared" % name)
            return TypeCheckError("@stage(post_agg) calc references %r, which is not a "
                                  "group key, window bound, aggregate or earlier calc" % name)
        compiled = compile_expression(calc.expression, output_names, params, row_relative=True,
                                      unknown=post_unknown, ts_parser=ts_parser)
        evaluate = _check_declared(calc.name, calc.type, compiled, "calc")
        output_names.define(calc.name, calc.type)
        post_calcs.append((calc.name, evaluate))

    referenced = _referenced_columns(program, schema_def, group_columns, window is not None)
    buckets = _evaluate_rows(dataset, row_ops, window, group_columns, referenced,
                             bad_records if bad_records is not None else BadRecordLog(False))

    scalar = window is None and not group_columns
    if scalar and not buckets:
        buckets[((None, None), ())] = []

    rows = []
    for (bounds, keys), records in buckets.items():
        values = {}
        for item, aggregate in aggregates:
            if item.column is None:
                inputs = [True] * len(records)
            else:
                inputs = [r[item.column] for r in records]
            values[item.alias] = aggregate.compute(inputs)
        rows.append(ResultRow(bounds[0], bounds[1], keys, values))
    rows.sort(key=lambda r: (_sort_key(r.window_start), tuple(_sort_key(k) for k in r.keys)))

    if post_calcs:
        table = []
        for position, row in enumerate(rows):
            data = dict(row.values)
            data.update(zip(group_columns, row.keys))
            if window is not None:
                data["window_start"] = row.window_start
                data["window_end"] = row.window_end
            table.append(_OutputRecord(data, position, table))
        for name, evaluate in post_calcs:
            for record in table:
                record.data[name] = evaluate(record)
        for row, record in zip(rows, table):
            for name, _ in post_calcs:
                row.values[name] = record.data[name]

    post = program.post_calcs
    return ResultSet(window is not None, group_columns, group_types, aliases, scalar, rows,
                     [c.name for c in post], [c.type for c in post])


def _referenced_columns(program, schema_def, group_columns, windowed):
    """Input columns the pipeline reads (directly or via schema calcs)."""
    names = set(group_columns)
    exprs = [c.expression for c in program.pre_calcs]
    if schema_def is not None:
        exprs.extend(f.expression for f in schema_def.calcs)
    for step in program.steps:
        exprs.append(step.predicate if isinstance(step, P.Filter) else step.expression)
    for expr in exprs:
        names.update(column_references(expr))
    names.update(item.column for item in program.aggregate.items if item.column is not None)
    if windowed:
        names.add("timestamp")
    return names


def _apply_row_ops(row_ops, record):
    """Run the row steps on one record; False if a filter drops it."""
    data = record.data
    for op in row_ops:
        if op[0] == "filter":
            if op[1](record) is not True:
                return False
        else:
            data[op[1]] = op[3](record)
    return True


def _evaluate_rows(dataset, row_ops, window, group_columns, referenced, log):
    """Evaluate row steps row by row and bucket the surviving rows by (window, keys)."""
    buckets = {}
    for entry in dataset.entries():
        tag = entry[0]
        if tag == "absent":
            missing = [n for n in entry[2] if n in referenced]
            if missing and log.strict:
                log.add(BadRecord(Provenance(entry[1], None, None), Q.MISSING_REQUIRED_FIELD,
                                  "input lacks column(s) %s" % ", ".join(missing),
                                  {"columns": missing}))
            continue
        if tag == "bad":
            log.add(entry[1])
            continue
        prov, data = entry[1], entry[2]
        failure = None
        try:
            keep = _apply_row_ops(row_ops, _RowRecord(data))
        except TypeCheckError as exc:
            failure = (Q.TYPE_ERROR, str(exc))
        except ExecutionError as exc:
            failure = (Q.RUNTIME_ERROR, str(exc))
        except (ArithmeticError, ValueError) as exc:
            failure = (Q.RUNTIME_ERROR, "evaluation failed: %s" % exc)
        if failure is not None:
            log.add(BadRecord(prov, failure[0], failure[1], {"values": data}))
            continue
        if not keep:
            continue
        bounds = (None, None)
        if window is not None:
            instant = data.get("timestamp")
            if instant is None:
                log.add(BadRecord(prov, Q.MISSING_REQUIRED_FIELD,
                                  "timestamp is null; the row cannot be assigned to a window",
                                  {"column": "timestamp", "values": data}))
                continue
            try:
                bounds = window.bounds(instant)
            except ExecutionError as exc:
                log.add(BadRecord(prov, Q.RUNTIME_ERROR, str(exc), {"values": data}))
                continue
        key = (bounds, tuple(data[c] for c in group_columns))
        buckets.setdefault(key, []).append(data)
    return buckets

content.content:
"""Declarative multi-source ingestion.

Secret: the ingest-config document (YAML or JSON) and its validation, how
source patterns are expanded and files assigned to sources by precedence,
and how each source's mapping (drop, rename, cast, defaults), schema
conversion, required-field checks and schema calcs turn raw file rows into
typed rows.
"""

import glob
import json
import math
import os
import re
from collections import OrderedDict, namedtuple
from datetime import date, datetime

from . import inputs
from . import quality as Q
from . import sources as S
from . import valuetypes as T
from .declarations import resolve_named_schema
from .dsl_parser import TYPE_NAMES
from .errors import ConfigError, ExecutionError, InputError, MtlError, TypeCheckError
from .expressions import cast_value, coerce, compile_expression, is_assignable
from .timestamps import TimestampParser

_SOURCE_NAME = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
_MAPPING_KEYS = ("drop", "rename", "cast", "defaults")

Defaults = namedtuple("Defaults", "tz timestamp_format nulls format recursive")

SourceSpec = namedtuple("SourceSpec", "name patterns recursive format schema precedence "
                                      "ts_parser nulls drop rename cast defaults required "
                                      "base_dir")
# patterns: path-or-glob strings; drop: tuple; rename/cast/defaults: OrderedDict;
# defaults values are typed raw values (see _typed); required: tuple


# ---------------------------------------------------------------------------
# The configuration document


def load_config(path, defaults):
    """Read and validate the ingest config; returns SourceSpecs in config order."""
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except OSError as exc:
        raise InputError("cannot read ingest config %r: %s" % (path, exc.strerror or exc))
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise ConfigError("ingest config %r is not valid UTF-8" % path)
    document = _parse_document(text, path)
    if isinstance(document, dict):
        if "sources" not in document:
            raise ConfigError("ingest config has no 'sources' list")
        entries = document["sources"]
    else:
        entries = document
    if not isinstance(entries, list) or not entries:
        raise ConfigError("ingest config 'sources' must be a non-empty list")
    base_dir = os.path.dirname(os.path.abspath(path))
    specs = []
    names = set()
    for index, entry in enumerate(entries):
        spec = _parse_source(index, entry, defaults, base_dir)
        if spec.name in names:
            raise ConfigError("source name %r is defined more than once" % spec.name)
        names.add(spec.name)
        specs.append(spec)
    return specs


def _parse_document(text, path):
    if path.lower().endswith(".json"):
        try:
            return json.loads(text)
        except ValueError as exc:
            raise ConfigError("malformed JSON ingest config: %s" % exc)
    try:
        import yaml
    except ImportError:  # pragma: no cover - PyYAML is a declared dependency
        try:
            return json.loads(text)
        except ValueError as exc:
            raise ConfigError("malformed ingest config (PyYAML unavailable): %s" % exc)
    try:
        return yaml.safe_load(text)
    except yaml.YAMLError as exc:
        raise ConfigError("malformed YAML ingest config: %s" % " ".join(str(exc).split()))


def _parse_source(index, entry, defaults, base_dir):
    if not isinstance(entry, dict):
        raise ConfigError("sources[%d] must be a mapping" % index)
    name = entry.get("name")
    if not isinstance(name, str) or not _SOURCE_NAME.match(name):
        raise ConfigError("sources[%d].name must be an identifier" % index)
    where = "source %r" % name

    patterns = entry.get("inputs")
    if isinstance(patterns, str):
        patterns = [patterns]
    if (not isinstance(patterns, list) or not patterns
            or not all(isinstance(p, str) and p.strip() for p in patterns)):
        raise ConfigError("%s: 'inputs' must be a non-empty list of paths or globs" % where)

    recursive = entry.get("recursive", defaults.recursive)
    if recursive is None:
        recursive = defaults.recursive
    if not isinstance(recursive, bool):
        raise ConfigError("%s: 'recursive' must be true or false" % where)

    fmt = entry.get("format")
    if fmt is None:
        fmt = defaults.format
    if not isinstance(fmt, str) or fmt.strip().lower() not in inputs.FORMATS:
        raise ConfigError("%s: 'format' must be one of %s" % (where, ", ".join(inputs.FORMATS)))
    fmt = fmt.strip().lower()

    schema = entry.get("schema")
    if schema is not None and (not isinstance(schema, str) or not _SOURCE_NAME.match(schema)):
        raise ConfigError("%s: 'schema' must be a schema name" % where)

    precedence = entry.get("precedence", 0)
    if precedence is None:
        precedence = 0
    if isinstance(precedence, float) and precedence.is_integer():
        precedence = int(precedence)
    if isinstance(precedence, bool) or not isinstance(precedence, int):
        raise ConfigError("%s: 'precedence' must be an integer" % where)

    tz = entry.get("tz")
    if tz is None:
        tz = defaults.tz
    ts_format = entry.get("timestamp_format", entry.get("timestamp-format"))
    if ts_format is None:
        ts_format = defaults.timestamp_format
    if not isinstance(tz, str) or not tz.strip():
        raise ConfigError("%s: 'tz' must be an IANA zone name" % where)
    if not isinstance(ts_format, (str, type(None))):
        raise ConfigError("%s: 'timestamp_format' must be a string" % where)
    try:
        ts_parser = TimestampParser(tz.strip(), ts_format)
    except MtlError as exc:
        raise ConfigError("%s: %s" % (where, exc))

    nulls = _nulls(entry.get("nulls"), defaults.nulls, where)

    mapping = entry.get("mapping")
    if mapping is None:
        mapping = {}
    if not isinstance(mapping, dict):
        raise ConfigError("%s: 'mapping' must be a mapping" % where)
    unknown = [k for k in mapping if k not in _MAPPING_KEYS]
    if unknown:
        raise ConfigError("%s: unknown mapping directive %r" % (where, unknown[0]))
    drop = tuple(_names(mapping.get("drop"), where, "mapping.drop"))
    rename = _str_map(mapping.get("rename"), where, "mapping.rename")
    targets = list(rename.values())
    for target in targets:
        if targets.count(target) > 1:
            raise ConfigError("%s: mapping.rename maps several columns to %r" % (where, target))
    cast = OrderedDict()
    for column, target in _str_map(mapping.get("cast"), where, "mapping.cast").items():
        lowered = target.strip().lower()
        if lowered not in TYPE_NAMES:
            raise ConfigError("%s: mapping.cast of %r to unknown type %r" % (where, column, target))
        cast[column] = lowered
    defaults_map = OrderedDict()
    raw_defaults = mapping.get("defaults")
    if raw_defaults is None:
        raw_defaults = {}
    if not isinstance(raw_defaults, dict):
        raise ConfigError("%s: mapping.defaults must be a mapping" % where)
    for column, value in raw_defaults.items():
        if not isinstance(column, str) or not column:
            raise ConfigError("%s: mapping.defaults keys must be column names" % where)
        typed = _typed(value, ts_parser)
        if typed is _INVALID:
            raise ConfigError("%s: mapping.defaults value for %r must be a scalar"
                              % (where, column))
        if typed is not None:
            defaults_map[column] = typed
    required = tuple(_names(entry.get("required"), where, "required"))

    return SourceSpec(name, tuple(p.strip() for p in patterns), recursive, fmt, schema,
                      precedence, ts_parser, nulls, drop, rename, cast, defaults_map, required,
                      base_dir)


def _nulls(value, fallback, where):
    if value is None:
        return fallback
    if isinstance(value, str):
        return frozenset(m.strip() for m in value.split(",") if m.strip() != "")
    if not isinstance(value, list):
        raise ConfigError("%s: 'nulls' must be a list of strings" % where)
    markers = set()
    for marker in value:
        if marker is None:  # an unquoted YAML null / ~
            markers.update(("null", "NULL", "Null", "~"))
        elif isinstance(marker, bool):
            markers.add("true" if marker else "false")
        elif isinstance(marker, (str, int, float)):
            markers.add(str(marker).strip())
        else:
            raise ConfigError("%s: 'nulls' must be a list of strings" % where)
    # "" is always null, as for --nulls; keep it out of the stripped marker set.
    return frozenset(m for m in markers if m != "")


def _names(value, where, what):
    if value is None:
        return []
    if isinstance(value, str):
        value = [value]
    if not isinstance(value, list) or not all(isinstance(v, str) and v for v in value):
        raise ConfigError("%s: %s must be a list of column names" % (where, what))
    return value


def _str_map(value, where, what):
    if value is None:
        return OrderedDict()
    if not isinstance(value, dict):
        raise ConfigError("%s: %s must be a mapping" % (where, what))
    result = OrderedDict()
    for key, target in value.items():
        if not isinstance(key, str) or not key or not isinstance(target, str) or not target:
            raise ConfigError("%s: %s must map column names to names" % (where, what))
        result[key] = target
    return result


_INVALID = object()


def _typed(value, ts_parser):
    """A config scalar as a raw value (see _Raw), None for null, _INVALID otherwise."""
    if value is None:
        return None
    if isinstance(value, bool):
        return ("v", T.BOOL, value)
    if isinstance(value, int):
        return ("v", T.INT, value)
    if isinstance(value, float):
        if not math.isfinite(value):
            return _INVALID
        return ("v", T.FLOAT, value)
    if isinstance(value, str):
        return ("t", value)
    if isinstance(value, datetime):
        return ("v", T.TIMESTAMP, ts_parser.localize(value))
    if isinstance(value, date):
        return ("v", T.TIMESTAMP, ts_parser.localize(datetime(value.year, value.month,
                                                              value.day)))
    return _INVALID


# ---------------------------------------------------------------------------
# File assignment


def assign_files(specs):
    """name -> files of that source (sorted by absolute path).

    A file matched by several sources goes to the one with the lowest
    precedence; equal lowest precedence is a configuration error.
    """
    matches = OrderedDict()   # realpath -> {source name: InputFile}
    for spec in specs:
        for pattern in spec.patterns:
            for key, entry in _expand(spec, pattern).items():
                matches.setdefault(key, OrderedDict()).setdefault(spec.name, entry)
    by_name = {spec.name: spec for spec in specs}
    assigned = OrderedDict((spec.name, []) for spec in specs)
    for key, claims in matches.items():
        best = min(by_name[n].precedence for n in claims)
        winners = [n for n in claims if by_name[n].precedence == best]
        if len(winners) > 1:
            raise ConfigError("file %r matches sources %s with equal precedence %d"
                              % (claims[winners[0]].path, ", ".join(repr(w) for w in winners),
                                 best))
        assigned[winners[0]].append(claims[winners[0]])
    for name in assigned:
        assigned[name].sort(key=lambda f: os.path.abspath(f.path))
    return assigned


def _expand(spec, pattern):
    """Files of one pattern; relative patterns are tried against the working
    directory first, then against the directory of the config file."""
    pattern = os.path.expanduser(pattern)
    candidates = [pattern]
    if not os.path.isabs(pattern):
        anchored = os.path.join(spec.base_dir, pattern)
        if os.path.abspath(pattern) != os.path.normpath(anchored):
            candidates.append(anchored)
    for candidate in candidates:
        if os.path.exists(candidate) or glob.has_magic(candidate):
            found = inputs.expand(candidate, spec.format, spec.recursive)
            if found:
                return found
    if not glob.has_magic(pattern) and not any(os.path.exists(c) for c in candidates):
        raise InputError("source %r: input %r does not exist" % (spec.name, pattern))
    return {}


# ---------------------------------------------------------------------------
# Typed rows of one source
#
# Raw values flowing through the mapping are tuples:
#   ("t", text)            a CSV/TSV cell
#   ("p", kind, value)     a Parquet value of logical `kind`
#   ("v", type, value)     an already typed value (after cast or from a default)


class SourceReader:
    """Static column types and (lazily) the typed rows of one configured source."""

    def __init__(self, spec, schemas, fallback_schema, files):
        self.spec = spec
        self.files = files
        self._rows = None
        self._mapped = None
        self.defaults = spec.defaults
        schema_name = spec.schema or fallback_schema
        if spec.schema is not None and spec.schema not in schemas:
            raise ConfigError("source %r uses schema %r, which the DSL does not define"
                              % (spec.name, spec.schema))
        self.schema = None if schema_name is None else resolve_named_schema(schemas,
                                                                            schema_name)
        if self.schema is not None:
            self.physical = OrderedDict(self.schema.physical)
            self._check_defaults()
            fields = self.schema.fields
            for name in spec.required:
                if name not in fields:
                    raise ConfigError("source %r: required field %r is not in schema %r"
                                      % (spec.name, name, self.schema.name))
            self.columns = OrderedDict((n, f.type) for n, f in fields.items())
            self._calcs = self._compile_calcs()
        else:
            self.physical = None      # inferred from the data on first use
            self.columns = None
            self._calcs = []

    # -- static -----------------------------------------------------------
    def _check_defaults(self):
        """Convert defaults of schema fields to the field types up front."""
        self.defaults = OrderedDict()
        for column, raw in self.spec.defaults.items():
            col_type = self.physical.get(column)
            if col_type is not None:
                if col_type == T.STRING and raw[0] == "v" and raw[1] != T.TIMESTAMP:
                    raw = ("t", _text_of(raw))
                try:
                    raw = ("v", col_type, _convert(raw, col_type, self._converter(column)))
                except S._CellError:
                    raise ConfigError("source %r: default for %r is not a valid %s"
                                      % (self.spec.name, column, col_type))
            self.defaults[column] = raw

    def _compile_calcs(self):
        names = _Types(self.physical)
        compiled = []
        for field in self.schema.calcs:
            result = compile_expression(field.expression, names, ts_parser=self.spec.ts_parser)
            if not is_assignable(field.type, result.type):
                raise TypeCheckError("schema field %r is declared %s but its expression is %s"
                                     % (field.name, field.type, result.type))
            names.define(field.name, field.type)
            compiled.append((field.name, coerce(field.type, result)))
        return compiled

    def _converter(self, column):
        return S._Converter(self.physical[column], self.spec.nulls, self.spec.ts_parser)

    def ensure_columns(self):
        """Column types; schema-less sources infer them from their files."""
        if self.columns is None:
            self._load()
        return self.columns

    # -- rows -------------------------------------------------------------
    def rows(self, log):
        """List of (provenance, values) of the rows that survived validation."""
        if self._rows is None:
            mapped = self._load()
            self._rows = self._convert_rows(mapped, log)
        return self._rows

    def _load(self):
        if self._mapped is None:
            mapped = []
            for entry in self.files:
                mapped.extend(self._read(entry))
            self._mapped = mapped
            if self.physical is None:
                self._infer(mapped)
        return self._mapped

    def _read(self, entry):
        table = S.read_file(entry)
        if table.kind == "parquet":
            table.load(set(table.columns), self.spec.ts_parser)
            columns = [(n,) + table.data[n] for n in table.columns if n in table.data]
            for index in range(table.nrows):
                prov = Q.Provenance(table.path, None, index + 1)
                raw = OrderedDict((n, ("p", kind, values[index])) for n, kind, values in columns)
                yield self._map(prov, raw)
            return
        header = table.columns
        width = len(header)
        for ordinal, (line, cells) in enumerate(table.rows, start=1):
            prov = Q.Provenance(table.path, line, ordinal)
            if len(cells) != width:
                if len(cells) < width:
                    classification = Q.MISSING_REQUIRED_FIELD
                    message = "record has %d fields, expected %d (missing: %s)" % (
                        len(cells), width, ", ".join(header[len(cells):]))
                else:
                    classification = Q.PARSE_TYPE_MISMATCH
                    message = "record has %d fields, expected %d" % (len(cells), width)
                yield ("bad", Q.BadRecord(prov, classification, message,
                                          {"fields": list(cells), "header": list(header)},
                                          error=InputError))
                continue
            yield self._map(prov, OrderedDict((h, ("t", c)) for h, c in zip(header, cells)))

    def _map(self, prov, raw):
        """Apply drop, rename, cast and defaults, in that order."""
        spec = self.spec
        for column in spec.drop:
            raw.pop(column, None)
        if spec.rename:
            renamed = OrderedDict()
            targets = {spec.rename[c] for c in raw if c in spec.rename}
            for column, value in raw.items():
                if column not in spec.rename and column not in targets:
                    renamed[column] = value
            for column, value in raw.items():
                if column in spec.rename:
                    renamed[spec.rename[column]] = value
            raw = renamed
        for column, target in spec.cast.items():
            if column not in raw:
                continue
            try:
                raw[column] = ("v", target, self._cast(raw[column], target))
            except S._CellError as err:
                return ("bad", Q.BadRecord(prov, err.classification,
                                           "column %r: cast to %s failed: %s"
                                           % (column, target, err.message),
                                           {"column": column, "value": _show(raw[column]),
                                            "cast": target}))
        for column, value in self.defaults.items():
            if column not in raw or self._is_null(raw[column]):
                raw[column] = value
        return ("row", prov, raw)

    def _is_null(self, raw):
        if raw[0] == "t":
            return raw[1] == "" or raw[1].strip() in self.spec.nulls
        value = raw[2]
        return value is None or (isinstance(value, float) and math.isnan(value))

    def _cast(self, raw, target):
        if self._is_null(raw):
            return None
        converter = S._Converter(target, self.spec.nulls, self.spec.ts_parser)
        if raw[0] == "t":
            return converter.text(raw[1])
        if raw[0] == "p":
            kind, value = raw[1], raw[2]
            if kind == "string":
                return converter.text(value)
            if kind == "binary":
                return converter.text(bytes(value).decode("utf-8", "replace"))
            if kind == "date":
                source = T.TIMESTAMP
                value = self.spec.ts_parser.localize(datetime(value.year, value.month,
                                                              value.day))
            elif kind == "decimal":
                source, value = T.FLOAT, float(value)
            elif kind in ("int", "float", "bool") or (kind == "timestamp"
                                                      and isinstance(value, datetime)):
                source = S._KIND_TYPES[kind]
            else:
                raise S._CellError(Q.PARQUET_TYPE_MISMATCH, "Parquet %s value %s cannot be "
                                   "cast to %s" % (kind, _show(raw), target))
        else:
            source, value = raw[1], raw[2]
        try:
            return cast_value(value, source, target, self.spec.ts_parser)
        except (TypeCheckError, ExecutionError, ValueError, OverflowError) as exc:
            raise S._CellError(Q.PARSE_TYPE_MISMATCH, "%s value %s cannot be cast to %s (%s)"
                               % (source, _show(raw), target, exc))

    def _infer(self, mapped):
        """Column types of a schema-less source (fixed event columns + inferred extras)."""
        seen = OrderedDict()
        for item in mapped:
            if item[0] == "row":
                for column, raw in item[2].items():
                    seen.setdefault(column, []).append(raw)
        types = OrderedDict(S.KNOWN)
        for column, raws in seen.items():
            if column in types:
                continue
            typed = {r[1] for r in raws if r[0] == "v" and r[2] is not None}
            kinds = {r[1] for r in raws if r[0] == "p" and r[2] is not None
                     and r[1] != "null"}
            cells = [r[1] for r in raws if r[0] == "t"]
            mapped_types = typed | {S._KIND_TYPES[k] for k in kinds}
            if not cells and mapped_types:
                if len(mapped_types) == 1:
                    types[column] = mapped_types.pop()
                    continue
                if mapped_types == {T.INT, T.FLOAT}:
                    types[column] = T.FLOAT
                    continue
            cells.extend(_text_of(r) for r in raws if r[0] != "t" and r[-1] is not None)
            types[column] = S._infer_text(cells, self.spec.nulls, self.spec.ts_parser)
        for column, target in self.spec.cast.items():
            if column in types:
                types[column] = target
        self.physical = types
        self.columns = OrderedDict(types)

    def _convert_rows(self, mapped, log):
        rows = []
        physical = self.physical
        converters = {n: self._converter(n) for n in physical}
        required = self.spec.required
        for item in mapped:
            if item[0] == "bad":
                log.add(item[1])
                continue
            prov, raw = item[1], item[2]
            values = OrderedDict()
            failure = None
            for name, col_type in physical.items():
                value = raw.get(name)
                try:
                    values[name] = None if value is None else _convert(value, col_type,
                                                                      converters[name])
                except S._CellError as err:
                    failure = Q.BadRecord(prov, err.classification,
                                          "column %r: %s" % (name, err.message),
                                          {"column": name, "value": _show(value),
                                           "expected_type": col_type})
                    break
            if failure is None:
                failure = self._missing(prov, values, required, physical)
            if failure is None:
                try:
                    for name, evaluate in self._calcs:
                        values[name] = evaluate(_Record(values))
                except (ExecutionError, TypeCheckError, ArithmeticError, ValueError) as exc:
                    failure = Q.BadRecord(prov, Q.RUNTIME_ERROR, str(exc), {"values": values})
            if failure is None:
                failure = self._missing(prov, values, required, None)
            if failure is not None:
                log.add(failure)
                continue
            rows.append((prov, values))
        return rows

    def _missing(self, prov, values, required, among):
        for name in required:
            if (among is None or name in among) and values.get(name) is None:
                return Q.BadRecord(prov, Q.MISSING_REQUIRED_FIELD,
                                   "required field %r is null" % name,
                                   {"column": name, "source": self.spec.name,
                                    "values": dict(values)})
        return None


def _convert(raw, col_type, converter):
    """Schema conversion of one mapped raw value; raises sources._CellError."""
    tag = raw[0]
    if tag == "t":
        return converter.text(raw[1])
    if tag == "p":
        return converter.parquet(raw[1], raw[2])
    value_type, value = raw[1], raw[2]
    if value is None:
        return None
    if value_type == col_type:
        return value
    if value_type == T.INT and col_type == T.FLOAT:
        return float(value)
    if value_type == T.STRING and col_type != T.STRING:
        return converter.text(value)
    raise S._CellError(Q.PARSE_TYPE_MISMATCH, "%s value %s does not conform to schema type %s"
                       % (value_type, _show(raw), col_type))


def _text_of(raw):
    if raw[0] == "p":
        return S._canonical_text(raw[1], raw[2])
    value = raw[2]
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, datetime):
        from .timestamps import format_utc
        return format_utc(value)
    return repr(value) if isinstance(value, float) else str(value)


def _show(raw):
    if raw is None:
        return None
    value = raw[-1]
    if isinstance(value, (datetime, date)):
        return str(value)
    return value


class _Types:
    def __init__(self, types):
        self._types = OrderedDict(types)

    def has(self, name):
        return name in self._types

    def type_of(self, name):
        return self._types[name]

    def define(self, name, value_type):
        self._types[name] = value_type


class _Record:
    __slots__ = ("data",)

    def __init__(self, data):
        self.data = data

    def get(self, name):
        return self.data.get(name)

tool_use_result.stdout:
"""Declarative multi-source ingestion.

Secret: the ingest-config document (YAML or JSON) and its validation, how
source patterns are expanded and files assigned to sources by precedence,
and how each source's mapping (drop, rename, cast, defaults), schema
conversion, required-field checks and schema calcs turn raw file rows into
typed rows.
"""

import glob
import json
import math
import os
import re
from collections import OrderedDict, namedtuple
from datetime import date, datetime

from . import inputs
from . import quality as Q
from . import sources as S
from . import valuetypes as T
from .declarations import resolve_named_schema
from .dsl_parser import TYPE_NAMES
from .errors import ConfigError, ExecutionError, InputError, MtlError, TypeCheckError
from .expressions import cast_value, coerce, compile_expression, is_assignable
from .timestamps import TimestampParser

_SOURCE_NAME = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
_MAPPING_KEYS = ("drop", "rename", "cast", "defaults")

Defaults = namedtuple("Defaults", "tz timestamp_format nulls format recursive")

SourceSpec = namedtuple("SourceSpec", "name patterns recursive format schema precedence "
                                      "ts_parser nulls drop rename cast defaults required "
                                      "base_dir")
# patterns: path-or-glob strings; drop: tuple; rename/cast/defaults: OrderedDict;
# defaults values are typed raw values (see _typed); required: tuple


# ---------------------------------------------------------------------------
# The configuration document


def load_config(path, defaults):
    """Read and validate the ingest config; returns SourceSpecs in config order."""
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except OSError as exc:
        raise InputError("cannot read ingest config %r: %s" % (path, exc.strerror or exc))
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise ConfigError("ingest config %r is not valid UTF-8" % path)
    document = _parse_document(text, path)
    if isinstance(document, dict):
        if "sources" not in document:
            raise ConfigError("ingest config has no 'sources' list")
        entries = document["sources"]
    else:
        entries = document
    if not isinstance(entries, list) or not entries:
        raise ConfigError("ingest config 'sources' must be a non-empty list")
    base_dir = os.path.dirname(os.path.abspath(path))
    specs = []
    names = set()
    for index, entry in enumerate(entries):
        spec = _parse_source(index, entry, defaults, base_dir)
        if spec.name in names:
            raise ConfigError("source name %r is defined more than once" % spec.name)
        names.add(spec.name)
        specs.append(spec)
    return specs


def _parse_document(text, path):
    if path.lower().endswith(".json"):
        try:
            return json.loads(text)
        except ValueError as exc:
            raise ConfigError("malformed JSON ingest config: %s" % exc)
    try:
        import yaml
    except ImportError:  # pragma: no cover - PyYAML is a declared dependency
        try:
            return json.loads(text)
        except ValueError as exc:
            raise ConfigError("malformed ingest config (PyYAML unavailable): %s" % exc)
    try:
        return yaml.safe_load(text)
    except yaml.YAMLError as exc:
        raise ConfigError("malformed YAML ingest config: %s" % " ".join(str(exc).split()))


def _parse_source(index, entry, defaults, base_dir):
    if not isinstance(entry, dict):
        raise ConfigError("sources[%d] must be a mapping" % index)
    name = entry.get("name")
    if not isinstance(name, str) or not _SOURCE_NAME.match(name):
        raise ConfigError("sources[%d].name must be an identifier" % index)
    where = "source %r" % name

    patterns = entry.get("inputs")
    if isinstance(patterns, str):
        patterns = [patterns]
    if (not isinstance(patterns, list) or not patterns
            or not all(isinstance(p, str) and p.strip() for p in patterns)):
        raise ConfigError("%s: 'inputs' must be a non-empty list of paths or globs" % where)

    recursive = entry.get("recursive", defaults.recursive)
    if recursive is None:
        recursive = defaults.recursive
    if not isinstance(recursive, bool):
        raise ConfigError("%s: 'recursive' must be true or false" % where)

    fmt = entry.get("format")
    if fmt is None:
        fmt = defaults.format
    if not isinstance(fmt, str) or fmt.strip().lower() not in inputs.FORMATS:
        raise ConfigError("%s: 'format' must be one of %s" % (where, ", ".join(inputs.FORMATS)))
    fmt = fmt.strip().lower()

    schema = entry.get("schema")
    if schema is not None and (not isinstance(schema, str) or not _SOURCE_NAME.match(schema)):
        raise ConfigError("%s: 'schema' must be a schema name" % where)

    precedence = entry.get("precedence", 0)
    if precedence is None:
        precedence = 0
    if isinstance(precedence, float) and precedence.is_integer():
        precedence = int(precedence)
    if isinstance(precedence, bool) or not isinstance(precedence, int):
        raise ConfigError("%s: 'precedence' must be an integer" % where)

    tz = entry.get("tz")
    if tz is None:
        tz = defaults.tz
    ts_format = entry.get("timestamp_format", entry.get("timestamp-format"))
    if ts_format is None:
        ts_format = defaults.timestamp_format
    if not isinstance(tz, str) or not tz.strip():
        raise ConfigError("%s: 'tz' must be an IANA zone name" % where)
    if not isinstance(ts_format, (str, type(None))):
        raise ConfigError("%s: 'timestamp_format' must be a string" % where)
    try:
        ts_parser = TimestampParser(tz.strip(), ts_format)
    except MtlError as exc:
        raise ConfigError("%s: %s" % (where, exc))

    nulls = _nulls(entry.get("nulls"), defaults.nulls, where)

    mapping = entry.get("mapping")
    if mapping is None:
        mapping = {}
    if not isinstance(mapping, dict):
        raise ConfigError("%s: 'mapping' must be a mapping" % where)
    unknown = [k for k in mapping if k not in _MAPPING_KEYS]
    if unknown:
        raise ConfigError("%s: unknown mapping directive %r" % (where, unknown[0]))
    drop = tuple(_names(mapping.get("drop"), where, "mapping.drop"))
    rename = _str_map(mapping.get("rename"), where, "mapping.rename")
    targets = list(rename.values())
    for target in targets:
        if targets.count(target) > 1:
            raise ConfigError("%s: mapping.rename maps several columns to %r" % (where, target))
    cast = OrderedDict()
    for column, target in _str_map(mapping.get("cast"), where, "mapping.cast").items():
        lowered = target.strip().lower()
        if lowered not in TYPE_NAMES:
            raise ConfigError("%s: mapping.cast of %r to unknown type %r" % (where, column, target))
        cast[column] = lowered
    defaults_map = OrderedDict()
    raw_defaults = mapping.get("defaults")
    if raw_defaults is None:
        raw_defaults = {}
    if not isinstance(raw_defaults, dict):
        raise ConfigError("%s: mapping.defaults must be a mapping" % where)
    for column, value in raw_defaults.items():
        if not isinstance(column, str) or not column:
            raise ConfigError("%s: mapping.defaults keys must be column names" % where)
        typed = _typed(value, ts_parser)
        if typed is _INVALID:
            raise ConfigError("%s: mapping.defaults value for %r must be a scalar"
                              % (where, column))
        if typed is not None:
            defaults_map[column] = typed
    required = tuple(_names(entry.get("required"), where, "required"))

    return SourceSpec(name, tuple(p.strip() for p in patterns), recursive, fmt, schema,
                      precedence, ts_parser, nulls, drop, rename, cast, defaults_map, required,
                      base_dir)


def _nulls(value, fallback, where):
    if value is None:
        return fallback
    if isinstance(value, str):
        return frozenset(m.strip() for m in value.split(",") if m.strip() != "")
    if not isinstance(value, list):
        raise ConfigError("%s: 'nulls' must be a list of strings" % where)
    markers = set()
    for marker in value:
        if marker is None:  # an unquoted YAML null / ~
            markers.update(("null", "NULL", "Null", "~"))
        elif isinstance(marker, bool):
            markers.add("true" if marker else "false")
        elif isinstance(marker, (str, int, float)):
            markers.add(str(marker).strip())
        else:
            raise ConfigError("%s: 'nulls' must be a list of strings" % where)
    # "" is always null, as for --nulls; keep it out of the stripped marker set.
    return frozenset(m for m in markers if m != "")


def _names(value, where, what):
    if value is None:
        return []
    if isinstance(value, str):
        value = [value]
    if not isinstance(value, list) or not all(isinstance(v, str) and v for v in value):
        raise ConfigError("%s: %s must be a list of column names" % (where, what))
    return value


def _str_map(value, where, what):
    if value is None:
        return OrderedDict()
    if not isinstance(value, dict):
        raise ConfigError("%s: %s must be a mapping" % (where, what))
    result = OrderedDict()
    for key, target in value.items():
        if not isinstance(key, str) or not key or not isinstance(target, str) or not target:
            raise ConfigError("%s: %s must map column names to names" % (where, what))
        result[key] = target
    return result


_INVALID = object()


def _typed(value, ts_parser):
    """A config scalar as a raw value (see _Raw), None for null, _INVALID otherwise."""
    if value is None:
        return None
    if isinstance(value, bool):
        return ("v", T.BOOL, value)
    if isinstance(value, int):
        return ("v", T.INT, value)
    if isinstance(value, float):
        if not math.isfinite(value):
            return _INVALID
        return ("v", T.FLOAT, value)
    if isinstance(value, str):
        return ("t", value)
    if isinstance(value, datetime):
        return ("v", T.TIMESTAMP, ts_parser.localize(value))
    if isinstance(value, date):
        return ("v", T.TIMESTAMP, ts_parser.localize(datetime(value.year, value.month,
                                                              value.day)))
    return _INVALID


# ---------------------------------------------------------------------------
# File assignment


def assign_files(specs):
    """name -> files of that source (sorted by absolute path).

    A file matched by several sources goes to the one with the lowest
    precedence; equal lowest precedence is a configuration error.
    """
    matches = OrderedDict()   # realpath -> {source name: InputFile}
    for spec in specs:
        for pattern in spec.patterns:
            for key, entry in _expand(spec, pattern).items():
                matches.setdefault(key, OrderedDict()).setdefault(spec.name, entry)
    by_name = {spec.name: spec for spec in specs}
    assigned = OrderedDict((spec.name, []) for spec in specs)
    for key, claims in matches.items():
        best = min(by_name[n].precedence for n in claims)
        winners = [n for n in claims if by_name[n].precedence == best]
        if len(winners) > 1:
            raise ConfigError("file %r matches sources %s with equal precedence %d"
                              % (claims[winners[0]].path, ", ".join(repr(w) for w in winners),
                                 best))
        assigned[winners[0]].append(claims[winners[0]])
    for name in assigned:
        assigned[name].sort(key=lambda f: os.path.abspath(f.path))
    return assigned


def _expand(spec, pattern):
    """Files of one pattern; relative patterns are tried against the working
    directory first, then against the directory of the config file."""
    pattern = os.path.expanduser(pattern)
    candidates = [pattern]
    if not os.path.isabs(pattern):
        anchored = os.path.join(spec.base_dir, pattern)
        if os.path.abspath(pattern) != os.path.normpath(anchored):
            candidates.append(anchored)
    for candidate in candidates:
        if os.path.exists(candidate) or glob.has_magic(candidate):
            found = inputs.expand(candidate, spec.format, spec.recursive)
            if found:
                return found
    if not glob.has_magic(pattern) and not any(os.path.exists(c) for c in candidates):
        raise InputError("source %r: input %r does not exist" % (spec.name, pattern))
    return {}


# ---------------------------------------------------------------------------
# Typed rows of one source
#
# Raw values flowing through the mapping are tuples:
#   ("t", text)            a CSV/TSV cell
#   ("p", kind, value)     a Parquet value of logical `kind`
#   ("v", type, value)     an already typed value (after cast or from a default)


class SourceReader:
    """Static column types and (lazily) the typed rows of one configured source."""

    def __init__(self, spec, schemas, fallback_schema, files):
        self.spec = spec
        self.files = files
        self._rows = None
        self._mapped = None
        self.defaults = spec.defaults
        schema_name = spec.schema or fallback_schema
        if spec.schema is not None and spec.schema not in schemas:
            raise ConfigError("source %r uses schema %r, which the DSL does not define"
                              % (spec.name, spec.schema))
        self.schema = None if schema_name is None else resolve_named_schema(schemas,
                                                                            schema_name)
        if self.schema is not None:
            self.physical = OrderedDict(self.schema.physical)
            self._check_defaults()
            fields = self.schema.fields
            for name in spec.required:
                if name not in fields:
                    raise ConfigError("source %r: required field %r is not in schema %r"
                                      % (spec.name, name, self.schema.name))
            self.columns = OrderedDict((n, f.type) for n, f in fields.items())
            self._calcs = self._compile_calcs()
        else:
            self.physical = None      # inferred from the data on first use
            self.columns = None
            self._calcs = []

    # -- static -----------------------------------------------------------
    def _check_defaults(self):
        """Convert defaults of schema fields to the field types up front."""
        self.defaults = OrderedDict()
        for column, raw in self.spec.defaults.items():
            col_type = self.physical.get(column)
            if col_type is not None:
                if col_type == T.STRING and raw[0] == "v" and raw[1] != T.TIMESTAMP:
                    raw = ("t", _text_of(raw))
                try:
                    raw = ("v", col_type, _convert(raw, col_type, self._converter(column)))
                except S._CellError:
                    raise ConfigError("source %r: default for %r is not a valid %s"
                                      % (self.spec.name, column, col_type))
            self.defaults[column] = raw

    def _compile_calcs(self):
        names = _Types(self.physical)
        compiled = []
        for field in self.schema.calcs:
            result = compile_expression(field.expression, names, ts_parser=self.spec.ts_parser)
            if not is_assignable(field.type, result.type):
                raise TypeCheckError("schema field %r is declared %s but its expression is %s"
                                     % (field.name, field.type, result.type))
            names.define(field.name, field.type)
            compiled.append((field.name, coerce(field.type, result)))
        return compiled

    def _converter(self, column):
        return S._Converter(self.physical[column], self.spec.nulls, self.spec.ts_parser)

    def ensure_columns(self):
        """Column types; schema-less sources infer them from their files."""
        if self.columns is None:
            self._load()
        return self.columns

    # -- rows -------------------------------------------------------------
    def rows(self, log):
        """List of (provenance, values) of the rows that survived validation."""
        if self._rows is None:
            mapped = self._load()
            self._rows = self._convert_rows(mapped, log)
        return self._rows

    def _load(self):
        if self._mapped is None:
            mapped = []
            for entry in self.files:
                mapped.extend(self._read(entry))
            self._mapped = mapped
            if self.physical is None:
                self._infer(mapped)
        return self._mapped

    def _read(self, entry):
        table = S.read_file(entry)
        if table.kind == "parquet":
            table.load(set(table.columns), self.spec.ts_parser)
            columns = [(n,) + table.data[n] for n in table.columns if n in table.data]
            for index in range(table.nrows):
                prov = Q.Provenance(table.path, None, index + 1)
                raw = OrderedDict((n, ("p", kind, values[index])) for n, kind, values in columns)
                yield self._map(prov, raw)
            return
        header = table.columns
        width = len(header)
        for ordinal, (line, cells) in enumerate(table.rows, start=1):
            prov = Q.Provenance(table.path, line, ordinal)
            if len(cells) != width:
                if len(cells) < width:
                    classification = Q.MISSING_REQUIRED_FIELD
                    message = "record has %d fields, expected %d (missing: %s)" % (
                        len(cells), width, ", ".join(header[len(cells):]))
                else:
                    classification = Q.PARSE_TYPE_MISMATCH
                    message = "record has %d fields, expected %d" % (len(cells), width)
                yield ("bad", Q.BadRecord(prov, classification, message,
                                          {"fields": list(cells), "header": list(header)},
                                          error=InputError))
                continue
            yield self._map(prov, OrderedDict((h, ("t", c)) for h, c in zip(header, cells)))

    def _map(self, prov, raw):
        """Apply drop, rename, cast and defaults, in that order."""
        spec = self.spec
        for column in spec.drop:
            raw.pop(column, None)
        if spec.rename:
            renamed = OrderedDict()
            targets = {spec.rename[c] for c in raw if c in spec.rename}
            for column, value in raw.items():
                if column not in spec.rename and column not in targets:
                    renamed[column] = value
            for column, value in raw.items():
                if column in spec.rename:
                    renamed[spec.rename[column]] = value
            raw = renamed
        for column, target in spec.cast.items():
            if column not in raw:
                continue
            try:
                raw[column] = ("v", target, self._cast(raw[column], target))
            except S._CellError as err:
                return ("bad", Q.BadRecord(prov, err.classification,
                                           "column %r: cast to %s failed: %s"
                                           % (column, target, err.message),
                                           {"column": column, "value": _show(raw[column]),
                                            "cast": target}))
        for column, value in self.defaults.items():
            if column not in raw or self._is_null(raw[column]):
                raw[column] = value
        return ("row", prov, raw)

    def _is_null(self, raw):
        if raw[0] == "t":
            return raw[1] == "" or raw[1].strip() in self.spec.nulls
        value = raw[2]
        return value is None or (isinstance(value, float) and math.isnan(value))

    def _cast(self, raw, target):
        if self._is_null(raw):
            return None
        converter = S._Converter(target, self.spec.nulls, self.spec.ts_parser)
        if raw[0] == "t":
            return converter.text(raw[1])
        if raw[0] == "p":
            kind, value = raw[1], raw[2]
            if kind == "string":
                return converter.text(value)
            if kind == "binary":
                return converter.text(bytes(value).decode("utf-8", "replace"))
            if kind == "date":
                source = T.TIMESTAMP
                value = self.spec.ts_parser.localize(datetime(value.year, value.month,
                                                              value.day))
            elif kind == "decimal":
                source, value = T.FLOAT, float(value)
            elif kind in ("int", "float", "bool") or (kind == "timestamp"
                                                      and isinstance(value, datetime)):
                source = S._KIND_TYPES[kind]
            else:
                raise S._CellError(Q.PARQUET_TYPE_MISMATCH, "Parquet %s value %s cannot be "
                                   "cast to %s" % (kind, _show(raw), target))
        else:
            source, value = raw[1], raw[2]
        try:
            return cast_value(value, source, target, self.spec.ts_parser)
        except (TypeCheckError, ExecutionError, ValueError, OverflowError) as exc:
            raise S._CellError(Q.PARSE_TYPE_MISMATCH, "%s value %s cannot be cast to %s (%s)"
                               % (source, _show(raw), target, exc))

    def _infer(self, mapped):
        """Column types of a schema-less source (fixed event columns + inferred extras)."""
        seen = OrderedDict()
        for item in mapped:
            if item[0] == "row":
                for column, raw in item[2].items():
                    seen.setdefault(column, []).append(raw)
        types = OrderedDict(S.KNOWN)
        for column, raws in seen.items():
            if column in types:
                continue
            typed = {r[1] for r in raws if r[0] == "v" and r[2] is not None}
            kinds = {r[1] for r in raws if r[0] == "p" and r[2] is not None
                     and r[1] != "null"}
            cells = [r[1] for r in raws if r[0] == "t"]
            mapped_types = typed | {S._KIND_TYPES[k] for k in kinds}
            if not cells and mapped_types:
                if len(mapped_types) == 1:
                    types[column] = mapped_types.pop()
                    continue
                if mapped_types == {T.INT, T.FLOAT}:
                    types[column] = T.FLOAT
                    continue
            cells.extend(_text_of(r) for r in raws if r[0] != "t" and r[-1] is not None)
            types[column] = S._infer_text(cells, self.spec.nulls, self.spec.ts_parser)
        for column, target in self.spec.cast.items():
            if column in types:
                types[column] = target
        self.physical = types
        self.columns = OrderedDict(types)

    def _convert_rows(self, mapped, log):
        rows = []
        physical = self.physical
        converters = {n: self._converter(n) for n in physical}
        required = self.spec.required
        for item in mapped:
            if item[0] == "bad":
                log.add(item[1])
                continue
            prov, raw = item[1], item[2]
            values = OrderedDict()
            failure = None
            for name, col_type in physical.items():
                value = raw.get(name)
                try:
                    values[name] = None if value is None else _convert(value, col_type,
                                                                      converters[name])
                except S._CellError as err:
                    failure = Q.BadRecord(prov, err.classification,
                                          "column %r: %s" % (name, err.message),
                                          {"column": name, "value": _show(value),
                                           "expected_type": col_type})
                    break
            if failure is None:
                failure = self._missing(prov, values, required, physical)
            if failure is None:
                try:
                    for name, evaluate in self._calcs:
                        values[name] = evaluate(_Record(values))
                except (ExecutionError, TypeCheckError, ArithmeticError, ValueError) as exc:
                    failure = Q.BadRecord(prov, Q.RUNTIME_ERROR, str(exc), {"values": values})
            if failure is None:
                failure = self._missing(prov, values, required, None)
            if failure is not None:
                log.add(failure)
                continue
            rows.append((prov, values))
        return rows

    def _missing(self, prov, values, required, among):
        for name in required:
            if (among is None or name in among) and values.get(name) is None:
                return Q.BadRecord(prov, Q.MISSING_REQUIRED_FIELD,
                                   "required field %r is null" % name,
                                   {"column": name, "source": self.spec.name,
                                    "values": dict(values)})
        return None


def _convert(raw, col_type, converter):
    """Schema conversion of one mapped raw value; raises sources._CellError."""
    tag = raw[0]
    if tag == "t":
        return converter.text(raw[1])
    if tag == "p":
        return converter.parquet(raw[1], raw[2])
    value_type, value = raw[1], raw[2]
    if value is None:
        return None
    if value_type == col_type:
        return value
    if value_type == T.INT and col_type == T.FLOAT:
        return float(value)
    if value_type == T.STRING and col_type != T.STRING:
        return converter.text(value)
    raise S._CellError(Q.PARSE_TYPE_MISMATCH, "%s value %s does not conform to schema type %s"
                       % (value_type, _show(raw), col_type))


def _text_of(raw):
    if raw[0] == "p":
        return S._canonical_text(raw[1], raw[2])
    value = raw[2]
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, datetime):
        from .timestamps import format_utc
        return format_utc(value)
    return repr(value) if isinstance(value, float) else str(value)


def _show(raw):
    if raw is None:
        return None
    value = raw[-1]
    if isinstance(value, (datetime, date)):
        return str(value)
    return value


class _Types:
    def __init__(self, types):
        self._types = OrderedDict(types)

    def has(self, name):
        return name in self._types

    def type_of(self, name):
        return self._types[name]

    def define(self, name, value_type):
        self._types[name] = value_type


class _Record:
    __slots__ = ("data",)

    def __init__(self, data):
        self.data = data

    def get(self, name):
        return self.data.get(name)

content.content:
"""Event sources: CSV, TSV (optionally gzipped) and Parquet files.

Secret: the text dialects and encoding, gzip handling, how Parquet logical
types are read, null markers, how raw cells and Parquet values are
reconciled with the column types (and how failures are classified), the
fixed event columns used when no schema is declared, and how types of
undeclared columns are inferred across all files.
"""

import csv
import gzip
import io
import math
import re
import zlib
from collections import OrderedDict
from datetime import date, datetime, timedelta
from decimal import Decimal

from . import inputs
from . import quality as Q
from . import timestamps
from . import valuetypes as T
from .dataset import Dataset
from .errors import InputError

KNOWN = OrderedDict([
    ("timestamp", T.TIMESTAMP),
    ("location", T.STRING),
    ("item", T.STRING),
    ("price", T.FLOAT),
    ("quantity", T.FLOAT),
    ("unit", T.STRING),
    ("category", T.STRING),
])
DEFAULT_NULLS = ("null", "NULL", "NaN")

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(\d+\.?\d*([eE][+-]?\d+)?|\.\d+([eE][+-]?\d+)?)$")
_EPOCH_NAIVE = datetime(1970, 1, 1)
_UNIT_MICROS = {"s": (1000000, 1), "ms": (1000, 1), "us": (1, 1), "ns": (1, 1000)}


def parse_null_markers(text):
    """The --nulls value as a marker set (None means the defaults)."""
    if text is None:
        return frozenset(DEFAULT_NULLS)
    return frozenset(m.strip() for m in text.split(",") if m.strip() != "")


class _CellError(Exception):
    def __init__(self, classification, message):
        Exception.__init__(self, message)
        self.classification = classification
        self.message = message


# ---------------------------------------------------------------------------
# Reading files


class _TextTable:
    kind = "text"

    def __init__(self, path, header, rows):
        self.path = path
        self.columns = header
        self.rows = rows          # list of (line, cells)


class _Unsupported:
    """Placeholder for a Parquet value of a type no DSL type can hold."""

    def __init__(self, type_name):
        self.type_name = type_name

    def __str__(self):
        return "<%s>" % self.type_name


class _OutOfRange:
    def __init__(self, raw):
        self.raw = raw

    def __str__(self):
        return "<timestamp out of range: %s>" % self.raw


class _ParquetTable:
    kind = "parquet"

    def __init__(self, path, handle):
        self.path = path
        self._handle = handle
        names = []
        for name in handle.schema_arrow.names:
            if name not in names:
                names.append(name)
        self.columns = names
        self.nrows = handle.metadata.num_rows
        self.data = {}            # name -> (kind, values)

    def load(self, wanted, ts_parser):
        names = [n for n in self.columns if n in wanted]
        try:
            table = self._handle.read(columns=names) if names else None
        except Exception as exc:
            raise InputError("cannot read Parquet %r: %s" % (self.path, exc))
        if table is not None:
            self.nrows = table.num_rows
            for name in names:
                index = table.schema.get_field_index(name)
                if index < 0:
                    index = table.schema.names.index(name)
                self.data[name] = _parquet_values(table.column(index), ts_parser)
        self._handle = None


def read_file(entry):
    """Read and structurally validate one input file (an inputs.InputFile)."""
    if entry.format == inputs.PARQUET:
        return _open_parquet(entry.path)
    data = _read_bytes(entry.path)
    if entry.gzipped or data[:2] == b"\x1f\x8b":
        try:
            data = gzip.decompress(data)
        except (OSError, EOFError, zlib.error) as exc:
            raise InputError("cannot decompress %r: %s" % (entry.path, exc))
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise InputError("%r is not valid UTF-8" % entry.path)
    delimiter = "\t" if entry.format == inputs.TSV else ","
    header, rows = _split(text, delimiter, entry.path)
    return _TextTable(entry.path, header, rows)


def _read_bytes(path):
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError as exc:
        raise InputError("cannot read %r: %s" % (path, exc.strerror or exc))


def _split(text, delimiter, path):
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter, quotechar='"',
                        doublequote=True, strict=True)
    rows = []
    previous = 0
    try:
        for cells in reader:
            line = previous + 1
            previous = reader.line_num
            if not cells or (len(cells) == 1 and cells[0].strip() == ""):
                continue
            rows.append((line, cells))
    except csv.Error as exc:
        raise InputError("malformed %s %r near line %d: %s"
                         % ("TSV" if delimiter == "\t" else "CSV", path, reader.line_num, exc))
    if not rows:
        raise InputError("%r has no header row" % path)
    header = [h.strip() for h in rows[0][1]]
    if any(h == "" for h in header):
        raise InputError("%r: header contains an empty column name" % path)
    if len(set(header)) != len(header):
        raise InputError("%r: header contains duplicate column names" % path)
    return header, rows[1:]


def _open_parquet(path):
    try:
        import pyarrow.parquet as pq
    except ImportError:  # pragma: no cover
        raise InputError("Parquet support requires pyarrow")
    try:
        handle = pq.ParquetFile(path)
        return _ParquetTable(path, handle)
    except Exception as exc:
        raise InputError("cannot read Parquet %r: %s" % (path, exc))


def _parquet_values(chunked, ts_parser):
    """(kind, python values) of one Parquet column; kind names the logical type."""
    import pyarrow as pa
    if chunked.num_chunks == 1:
        arr = chunked.chunk(0)
    elif chunked.num_chunks == 0:
        arr = pa.array([], chunked.type)
    else:
        arr = pa.concat_arrays(chunked.chunks)
    t = arr.type
    if pa.types.is_dictionary(t):
        arr = arr.dictionary_decode()
        t = arr.type
    if pa.types.is_timestamp(t):
        scale, divisor = _UNIT_MICROS[t.unit]
        raw = arr.cast(pa.int64()).to_pylist()
        values = [None if v is None else _instant(v * scale // divisor, t.tz is not None,
                                                  ts_parser) for v in raw]
        return "timestamp", values
    if pa.types.is_date(t):
        return "date", arr.to_pylist()
    if pa.types.is_boolean(t):
        return "bool", arr.to_pylist()
    if pa.types.is_integer(t):
        return "int", arr.to_pylist()
    if pa.types.is_floating(t):
        if t != pa.float64():
            arr = arr.cast(pa.float64())
        return "float", arr.to_pylist()
    if pa.types.is_decimal(t):
        return "decimal", arr.to_pylist()
    if pa.types.is_string(t) or pa.types.is_large_string(t) or _is(pa, "is_string_view", t):
        return "string", arr.to_pylist()
    if (pa.types.is_binary(t) or pa.types.is_large_binary(t)
            or pa.types.is_fixed_size_binary(t) or _is(pa, "is_binary_view", t)):
        return "binary", arr.to_pylist()
    if pa.types.is_null(t):
        return "null", [None] * len(arr)
    nulls = arr.is_null().to_pylist()
    marker = _Unsupported(str(t))
    return "other", [None if n else marker for n in nulls]


def _is(pa, predicate, t):
    test = getattr(pa.types, predicate, None)
    return bool(test and test(t))


def _instant(micros, aware, ts_parser):
    try:
        if aware:
            return timestamps.from_epoch_micros(micros)
        return ts_parser.localize(_EPOCH_NAIVE + timedelta(microseconds=micros))
    except Exception:
        return _OutOfRange(micros)


# ---------------------------------------------------------------------------
# Value conversion


class _Converter:
    """Turns raw cells / Parquet values into values of one column type."""

    def __init__(self, col_type, nulls, ts_parser):
        self.type = col_type
        self.nulls = nulls
        self.ts_parser = ts_parser
        self.iso_parser = ts_parser.iso_only()

    def text(self, cell, parser=None):
        stripped = cell.strip()
        if cell == "" or stripped in self.nulls:
            return None
        col_type = self.type
        if col_type == T.STRING:
            return cell
        if stripped == "":
            return None
        if col_type in (T.INT, T.FLOAT) and stripped.lower() == "nan":
            return None
        if col_type == T.INT:
            if not _INT_RE.match(stripped):
                raise _CellError(Q.PARSE_TYPE_MISMATCH, "value %r is not a valid int" % cell)
            return int(stripped)
        if col_type == T.FLOAT:
            if not _FLOAT_RE.match(stripped):
                raise _CellError(Q.PARSE_TYPE_MISMATCH, "value %r is not a valid float" % cell)
            value = float(stripped)
            if not math.isfinite(value):
                raise _CellError(Q.PARSE_TYPE_MISMATCH, "value %r is out of range for float"
                                 % cell)
            return value
        if col_type == T.BOOL:
            lowered = stripped.lower()
            if lowered not in ("true", "false"):
                raise _CellError(Q.PARSE_TYPE_MISMATCH, "value %r is not a valid bool" % cell)
            return lowered == "true"
        try:
            return (parser or self.ts_parser).parse(stripped)
        except (ValueError, OverflowError) as exc:
            raise _CellError(Q.TIMESTAMP_PARSE_ERROR, "value %r is not a valid timestamp (%s)"
                             % (cell, exc))

    def parquet(self, kind, value):
        """Reconcile a Parquet value of logical `kind` with the column type."""
        if value is None:
            return None
        col_type = self.type
        if kind == "string":
            try:
                return self.text(value, self.iso_parser)
            except _CellError as err:
                raise _CellError(Q.PARQUET_TYPE_MISMATCH,
                                 "Parquet string cannot be read as %s: %s" % (col_type, err))
        if kind == "binary" and col_type == T.STRING:
            try:
                return self.text(bytes(value).decode("utf-8"))
            except UnicodeDecodeError:
                pass
        elif col_type == T.INT:
            if kind == "int":
                return value
            if kind == "decimal" and value.is_finite() and value == value.to_integral_value():
                return int(value)
        elif col_type == T.FLOAT:
            if kind in ("int", "float", "decimal"):
                result = float(value)
                if math.isnan(result):
                    return None
                if math.isfinite(result):
                    return result
        elif col_type == T.BOOL:
            if kind == "bool":
                return value
        elif col_type == T.TIMESTAMP:
            if kind == "timestamp" and isinstance(value, datetime):
                return value
            if kind == "date" and isinstance(value, date):
                try:
                    return self.ts_parser.localize(datetime(value.year, value.month, value.day))
                except (OverflowError, ValueError):
                    pass
        raise _CellError(Q.PARQUET_TYPE_MISMATCH, "Parquet %s value %s cannot be read as %s"
                         % (kind, _show(value), col_type))


def _show(value):
    if isinstance(value, (datetime, date, Decimal, _Unsupported, _OutOfRange)):
        return str(value)
    return repr(value)


def _canonical_text(kind, value):
    """Text form of a Parquet value, for columns whose type is inferred from text."""
    if value is None:
        return ""
    if kind == "bool":
        return "true" if value else "false"
    if kind == "timestamp" and isinstance(value, datetime):
        return timestamps.format_utc(value)
    if kind == "float":
        return repr(value)
    if kind == "binary":
        return bytes(value).decode("utf-8", "replace")
    return str(value)


_KIND_TYPES = {"int": T.INT, "float": T.FLOAT, "decimal": T.FLOAT, "bool": T.BOOL,
               "string": T.STRING, "binary": T.STRING, "timestamp": T.TIMESTAMP,
               "date": T.TIMESTAMP, "other": T.STRING}


def _infer_text(cells, nulls, ts_parser):
    present = [c.strip() for c in cells if c.strip() != "" and c.strip() not in nulls]
    if not present:
        return T.STRING
    if all(_INT_RE.match(c) for c in present):
        return T.INT
    numeric = [c for c in present if c.lower() != "nan"]
    if numeric and all(_FLOAT_RE.match(c) for c in numeric):
        return T.FLOAT
    if all(c in ("true", "false") for c in present):
        return T.BOOL
    if all(ts_parser.looks_like_timestamp(c) for c in present):
        return T.TIMESTAMP
    return T.STRING


# ---------------------------------------------------------------------------
# Building the dataset


def load(entries):
    """Read every input file (structural checks only)."""
    return [read_file(e) for e in entries]


def build_dataset(tables, ts_parser, nulls, declared=None):
    """A Dataset over all tables.

    declared: name -> type of the schema's physical fields; when None the
    fixed event columns are used and other columns are exposed with
    inferred types.
    """
    if declared is not None:
        types = OrderedDict(declared)
        for table in tables:
            if table.kind == "parquet":
                table.load(set(types), ts_parser)
        plans = {}
    else:
        types = OrderedDict(KNOWN)
        extras = []
        for table in tables:
            for name in table.columns:
                if name not in types and name not in extras:
                    extras.append(name)
        for table in tables:
            if table.kind == "parquet":
                table.load(set(types) | set(extras), ts_parser)
        plans = {}
        for name in extras:
            types[name], plans[name] = _plan_extra(name, tables, nulls, ts_parser)
    converters = {name: _Converter(t, nulls, ts_parser) for name, t in types.items()}
    names = list(types)

    def entries():
        for table in tables:
            absent = [n for n in names if n not in table.columns]
            yield ("absent", table.path, absent)
            if table.kind == "parquet":
                rows = _parquet_rows(table, names, converters, plans)
            else:
                rows = _text_rows(table, names, converters)
            for item in rows:
                yield item

    return Dataset(names, [types[n] for n in names], entries)


def _plan_extra(name, tables, nulls, ts_parser):
    """(type, textual) for an undeclared column; textual means Parquet values go via text."""
    cells = []
    kinds = set()
    for table in tables:
        if name not in table.columns:
            continue
        if table.kind == "parquet":
            kind, _ = table.data[name]
            if kind != "null":
                kinds.add(kind)
        else:
            pos = table.columns.index(name)
            cells.extend(cells_[pos] for _, cells_ in table.rows if pos < len(cells_))
    present = [c for c in cells if c.strip() != "" and c.strip() not in nulls]
    if not present and kinds:
        mapped = {_KIND_TYPES[k] for k in kinds}
        if len(mapped) == 1:
            return mapped.pop(), False
        if mapped == {T.INT, T.FLOAT}:
            return T.FLOAT, False
    for table in tables:
        if table.kind == "parquet" and name in table.data:
            kind, values = table.data[name]
            cells.extend(_canonical_text(kind, v) for v in values if v is not None)
    return _infer_text(cells, nulls, ts_parser), True


def _text_rows(table, names, converters):
    header = table.columns
    width = len(header)
    positions = [(name, header.index(name) if name in header else None) for name in names]
    for ordinal, (line, cells) in enumerate(table.rows, start=1):
        prov = Q.Provenance(table.path, line, ordinal)
        if len(cells) != width:
            if len(cells) < width:
                classification = Q.MISSING_REQUIRED_FIELD
                message = "record has %d fields, expected %d (missing: %s)" % (
                    len(cells), width, ", ".join(header[len(cells):]))
            else:
                classification = Q.PARSE_TYPE_MISMATCH
                message = "record has %d fields, expected %d" % (len(cells), width)
            yield ("bad", Q.BadRecord(prov, classification, message,
                                      {"fields": list(cells), "header": list(header)},
                                      error=InputError))
            continue
        values = {}
        failure = None
        for name, pos in positions:
            if pos is None:
                values[name] = None
                continue
            converter = converters[name]
            try:
                values[name] = converter.text(cells[pos])
            except _CellError as err:
                failure = (name, cells[pos], converter.type, err)
                break
        if failure is None:
            yield ("row", prov, values)
            continue
        name, raw, col_type, err = failure
        yield ("bad", Q.BadRecord(prov, err.classification, "column %r: %s" % (name, err.message),
                                  {"column": name, "value": raw, "expected_type": col_type,
                                   "record": dict(zip(header, cells))}))


def _parquet_rows(table, names, converters, plans):
    columns = []
    for name in names:
        if name in table.data:
            kind, values = table.data[name]
            columns.append((name, kind, values))
        else:
            columns.append((name, None, None))
    for index in range(table.nrows):
        prov = Q.Provenance(table.path, None, index + 1)
        values = {}
        failure = None
        for name, kind, column in columns:
            if column is None:
                values[name] = None
                continue
            raw = column[index]
            converter = converters[name]
            try:
                if plans.get(name):
                    values[name] = (None if raw is None
                                    else converter.text(_canonical_text(kind, raw)))
                else:
                    values[name] = converter.parquet(kind, raw)
            except _CellError as err:
                failure = (name, raw, kind, converter.type, err)
                break
        if failure is None:
            yield ("row", prov, values)
            continue
        name, raw, kind, col_type, err = failure
        record = {n: (c[index] if c is not None else None) for n, _, c in columns}
        yield ("bad", Q.BadRecord(prov, err.classification, "column %r: %s" % (name, err.message),
                                  {"column": name, "value": raw, "parquet_type": kind,
                                   "expected_type": col_type, "record": record}))
"""Input discovery.

Secret: how --input arguments (files, directories, globs) expand to the
effective set of files, which files a directory walk picks up, how the
format of each file is decided from its name, and the canonical order in
which files are processed.
"""

import glob
import os
from collections import namedtuple

from .errors import InputError

CSV = "csv"
TSV = "tsv"
PARQUET = "parquet"
AUTO = "auto"
FORMATS = (CSV, TSV, PARQUET, AUTO)

InputFile = namedtuple("InputFile", "path format gzipped")

_SUFFIXES = (
    (".csv.gz", CSV, True),
    (".tsv.gz", TSV, True),
    (".csv", CSV, False),
    (".tsv", TSV, False),
    (".parquet", PARQUET, False),
)


def detect(name, forced):
    """(format, gzipped) for a file name, or None if it cannot be decided."""
    lowered = name.lower()
    for suffix, fmt, gz in _SUFFIXES:
        if lowered.endswith(suffix):
            return fmt, gz
    if forced in (CSV, TSV, PARQUET):
        return forced, lowered.endswith(".gz")
    return None


def _hidden(name):
    return name.startswith(".")


def _walk(directory, recursive):
    found = []
    if recursive:
        for root, dirs, files in os.walk(directory):
            dirs[:] = sorted(d for d in dirs if not _hidden(d))
            found.extend(os.path.join(root, f) for f in files if not _hidden(f))
    else:
        try:
            names = os.listdir(directory)
        except OSError as exc:
            raise InputError("cannot list directory %r: %s" % (directory, exc.strerror or exc))
        found.extend(os.path.join(directory, n) for n in names if not _hidden(n))
    return [p for p in found if os.path.isfile(p)]


def expand(spec, forced=AUTO, recursive=False):
    """Files named by one path-or-glob, as a dict realpath -> InputFile.

    An explicitly named file must have a recognisable format and a path
    that is neither a file, a directory nor a glob is an error; files
    reached through a directory or a glob are skipped when their format
    cannot be decided.
    """
    chosen = {}

    def add(path, explicit):
        name = os.path.basename(path)
        if not explicit and name.startswith("_") and detect(name, AUTO) is None:
            return  # marker files such as _SUCCESS
        detected = detect(name, forced)
        if detected is None:
            if explicit:
                raise InputError("cannot determine the format of %r (use --format)" % path)
            return
        display = os.path.normpath(path)
        key = os.path.realpath(path)
        current = chosen.get(key)
        if current is None or display < current.path:
            chosen[key] = InputFile(display, detected[0], detected[1])

    if os.path.isdir(spec):
        for path in _walk(spec, recursive):
            add(path, False)
    elif os.path.isfile(spec):
        add(spec, True)
    elif glob.has_magic(spec):
        for match in sorted(glob.glob(spec, recursive=True)):
            if os.path.isdir(match):
                for path in _walk(match, recursive):
                    add(path, False)
            elif os.path.isfile(match):
                add(match, False)
    else:
        raise InputError("input %r does not exist" % spec)
    return chosen


def resolve(specs, recursive=False, forced=AUTO):
    """Expand (path-or-glob, forced_format) pairs into a sorted list of InputFile."""
    chosen = {}
    for spec, override in specs:
        for key, entry in expand(spec, override or forced, recursive).items():
            current = chosen.get(key)
            if current is None or entry.path < current.path:
                chosen[key] = entry
    if not chosen:
        raise InputError("no input files found")
    return sorted(chosen.values(), key=lambda f: f.path)
"""Input table.

Secret: how the column schema and the stream of input rows are stored.
Callers see column names/types and an ordered stream of entries.
"""


class Dataset:
    """Column schema plus a re-iterable stream of entries, in canonical order.

    Each entry is one of
      ("absent", path, names)  -- a file starts; `names` are columns it lacks
      ("row", provenance, values)  -- values: name -> value (None is null)
      ("bad", BadRecord)       -- a row that could not be read
    """

    def __init__(self, names, types, entries):
        self._names = list(names)
        self._types = list(types)
        self._index = {n: i for i, n in enumerate(self._names)}
        self._entries = entries

    def has(self, name):
        return name in self._index

    def type_of(self, name):
        return self._types[self._index[name]]

    @property
    def names(self):
        return tuple(self._names)

    def entries(self):
        return self._entries()

tool_use_result.stdout:
"""Event sources: CSV, TSV (optionally gzipped) and Parquet files.

Secret: the text dialects and encoding, gzip handling, how Parquet logical
types are read, null markers, how raw cells and Parquet values are
reconciled with the column types (and how failures are classified), the
fixed event columns used when no schema is declared, and how types of
undeclared columns are inferred across all files.
"""

import csv
import gzip
import io
import math
import re
import zlib
from collections import OrderedDict
from datetime import date, datetime, timedelta
from decimal import Decimal

from . import inputs
from . import quality as Q
from . import timestamps
from . import valuetypes as T
from .dataset import Dataset
from .errors import InputError

KNOWN = OrderedDict([
    ("timestamp", T.TIMESTAMP),
    ("location", T.STRING),
    ("item", T.STRING),
    ("price", T.FLOAT),
    ("quantity", T.FLOAT),
    ("unit", T.STRING),
    ("category", T.STRING),
])
DEFAULT_NULLS = ("null", "NULL", "NaN")

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(\d+\.?\d*([eE][+-]?\d+)?|\.\d+([eE][+-]?\d+)?)$")
_EPOCH_NAIVE = datetime(1970, 1, 1)
_UNIT_MICROS = {"s": (1000000, 1), "ms": (1000, 1), "us": (1, 1), "ns": (1, 1000)}


def parse_null_markers(text):
    """The --nulls value as a marker set (None means the defaults)."""
    if text is None:
        return frozenset(DEFAULT_NULLS)
    return frozenset(m.strip() for m in text.split(",") if m.strip() != "")


class _CellError(Exception):
    def __init__(self, classification, message):
        Exception.__init__(self, message)
        self.classification = classification
        self.message = message


# ---------------------------------------------------------------------------
# Reading files


class _TextTable:
    kind = "text"

    def __init__(self, path, header, rows):
        self.path = path
        self.columns = header
        self.rows = rows          # list of (line, cells)


class _Unsupported:
    """Placeholder for a Parquet value of a type no DSL type can hold."""

    def __init__(self, type_name):
        self.type_name = type_name

    def __str__(self):
        return "<%s>" % self.type_name


class _OutOfRange:
    def __init__(self, raw):
        self.raw = raw

    def __str__(self):
        return "<timestamp out of range: %s>" % self.raw


class _ParquetTable:
    kind = "parquet"

    def __init__(self, path, handle):
        self.path = path
        self._handle = handle
        names = []
        for name in handle.schema_arrow.names:
            if name not in names:
                names.append(name)
        self.columns = names
        self.nrows = handle.metadata.num_rows
        self.data = {}            # name -> (kind, values)

    def load(self, wanted, ts_parser):
        names = [n for n in self.columns if n in wanted]
        try:
            table = self._handle.read(columns=names) if names else None
        except Exception as exc:
            raise InputError("cannot read Parquet %r: %s" % (self.path, exc))
        if table is not None:
            self.nrows = table.num_rows
            for name in names:
                index = table.schema.get_field_index(name)
                if index < 0:
                    index = table.schema.names.index(name)
                self.data[name] = _parquet_values(table.column(index), ts_parser)
        self._handle = None


def read_file(entry):
    """Read and structurally validate one input file (an inputs.InputFile)."""
    if entry.format == inputs.PARQUET:
        return _open_parquet(entry.path)
    data = _read_bytes(entry.path)
    if entry.gzipped or data[:2] == b"\x1f\x8b":
        try:
            data = gzip.decompress(data)
        except (OSError, EOFError, zlib.error) as exc:
            raise InputError("cannot decompress %r: %s" % (entry.path, exc))
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise InputError("%r is not valid UTF-8" % entry.path)
    delimiter = "\t" if entry.format == inputs.TSV else ","
    header, rows = _split(text, delimiter, entry.path)
    return _TextTable(entry.path, header, rows)


def _read_bytes(path):
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError as exc:
        raise InputError("cannot read %r: %s" % (path, exc.strerror or exc))


def _split(text, delimiter, path):
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter, quotechar='"',
                        doublequote=True, strict=True)
    rows = []
    previous = 0
    try:
        for cells in reader:
            line = previous + 1
            previous = reader.line_num
            if not cells or (len(cells) == 1 and cells[0].strip() == ""):
                continue
            rows.append((line, cells))
    except csv.Error as exc:
        raise InputError("malformed %s %r near line %d: %s"
                         % ("TSV" if delimiter == "\t" else "CSV", path, reader.line_num, exc))
    if not rows:
        raise InputError("%r has no header row" % path)
    header = [h.strip() for h in rows[0][1]]
    if any(h == "" for h in header):
        raise InputError("%r: header contains an empty column name" % path)
    if len(set(header)) != len(header):
        raise InputError("%r: header contains duplicate column names" % path)
    return header, rows[1:]


def _open_parquet(path):
    try:
        import pyarrow.parquet as pq
    except ImportError:  # pragma: no cover
        raise InputError("Parquet support requires pyarrow")
    try:
        handle = pq.ParquetFile(path)
        return _ParquetTable(path, handle)
    except Exception as exc:
        raise InputError("cannot read Parquet %r: %s" % (path, exc))


def _parquet_values(chunked, ts_parser):
    """(kind, python values) of one Parquet column; kind names the logical type."""
    import pyarrow as pa
    if chunked.num_chunks == 1:
        arr = chunked.chunk(0)
    elif chunked.num_chunks == 0:
        arr = pa.array([], chunked.type)
    else:
        arr = pa.concat_arrays(chunked.chunks)
    t = arr.type
    if pa.types.is_dictionary(t):
        arr = arr.dictionary_decode()
        t = arr.type
    if pa.types.is_timestamp(t):
        scale, divisor = _UNIT_MICROS[t.unit]
        raw = arr.cast(pa.int64()).to_pylist()
        values = [None if v is None else _instant(v * scale // divisor, t.tz is not None,
                                                  ts_parser) for v in raw]
        return "timestamp", values
    if pa.types.is_date(t):
        return "date", arr.to_pylist()
    if pa.types.is_boolean(t):
        return "bool", arr.to_pylist()
    if pa.types.is_integer(t):
        return "int", arr.to_pylist()
    if pa.types.is_floating(t):
        if t != pa.float64():
            arr = arr.cast(pa.float64())
        return "float", arr.to_pylist()
    if pa.types.is_decimal(t):
        return "decimal", arr.to_pylist()
    if pa.types.is_string(t) or pa.types.is_large_string(t) or _is(pa, "is_string_view", t):
        return "string", arr.to_pylist()
    if (pa.types.is_binary(t) or pa.types.is_large_binary(t)
            or pa.types.is_fixed_size_binary(t) or _is(pa, "is_binary_view", t)):
        return "binary", arr.to_pylist()
    if pa.types.is_null(t):
        return "null", [None] * len(arr)
    nulls = arr.is_null().to_pylist()
    marker = _Unsupported(str(t))
    return "other", [None if n else marker for n in nulls]


def _is(pa, predicate, t):
    test = getattr(pa.types, predicate, None)
    return bool(test and test(t))


def _instant(micros, aware, ts_parser):
    try:
        if aware:
            return timestamps.from_epoch_micros(micros)
        return ts_parser.localize(_EPOCH_NAIVE + timedelta(microseconds=micros))
    except Exception:
        return _OutOfRange(micros)


# ---------------------------------------------------------------------------
# Value conversion


class _Converter:
    """Turns raw cells / Parquet values into values of one column type."""

    def __init__(self, col_type, nulls, ts_parser):
        self.type = col_type
        self.nulls = nulls
        self.ts_parser = ts_parser
        self.iso_parser = ts_parser.iso_only()

    def text(self, cell, parser=None):
        stripped = cell.strip()
        if cell == "" or stripped in self.nulls:
            return None
        col_type = self.type
        if col_type == T.STRING:
            return cell
        if stripped == "":
            return None
        if col_type in (T.INT, T.FLOAT) and stripped.lower() == "nan":
            return None
        if col_type == T.INT:
            if not _INT_RE.match(stripped):
                raise _CellError(Q.PARSE_TYPE_MISMATCH, "value %r is not a valid int" % cell)
            return int(stripped)
        if col_type == T.FLOAT:
            if not _FLOAT_RE.match(stripped):
                raise _CellError(Q.PARSE_TYPE_MISMATCH, "value %r is not a valid float" % cell)
            value = float(stripped)
            if not math.isfinite(value):
                raise _CellError(Q.PARSE_TYPE_MISMATCH, "value %r is out of range for float"
                                 % cell)
            return value
        if col_type == T.BOOL:
            lowered = stripped.lower()
            if lowered not in ("true", "false"):
                raise _CellError(Q.PARSE_TYPE_MISMATCH, "value %r is not a valid bool" % cell)
            return lowered == "true"
        try:
            return (parser or self.ts_parser).parse(stripped)
        except (ValueError, OverflowError) as exc:
            raise _CellError(Q.TIMESTAMP_PARSE_ERROR, "value %r is not a valid timestamp (%s)"
                             % (cell, exc))

    def parquet(self, kind, value):
        """Reconcile a Parquet value of logical `kind` with the column type."""
        if value is None:
            return None
        col_type = self.type
        if kind == "string":
            try:
                return self.text(value, self.iso_parser)
            except _CellError as err:
                raise _CellError(Q.PARQUET_TYPE_MISMATCH,
                                 "Parquet string cannot be read as %s: %s" % (col_type, err))
        if kind == "binary" and col_type == T.STRING:
            try:
                return self.text(bytes(value).decode("utf-8"))
            except UnicodeDecodeError:
                pass
        elif col_type == T.INT:
            if kind == "int":
                return value
            if kind == "decimal" and value.is_finite() and value == value.to_integral_value():
                return int(value)
        elif col_type == T.FLOAT:
            if kind in ("int", "float", "decimal"):
                result = float(value)
                if math.isnan(result):
                    return None
                if math.isfinite(result):
                    return result
        elif col_type == T.BOOL:
            if kind == "bool":
                return value
        elif col_type == T.TIMESTAMP:
            if kind == "timestamp" and isinstance(value, datetime):
                return value
            if kind == "date" and isinstance(value, date):
                try:
                    return self.ts_parser.localize(datetime(value.year, value.month, value.day))
                except (OverflowError, ValueError):
                    pass
        raise _CellError(Q.PARQUET_TYPE_MISMATCH, "Parquet %s value %s cannot be read as %s"
                         % (kind, _show(value), col_type))


def _show(value):
    if isinstance(value, (datetime, date, Decimal, _Unsupported, _OutOfRange)):
        return str(value)
    return repr(value)


def _canonical_text(kind, value):
    """Text form of a Parquet value, for columns whose type is inferred from text."""
    if value is None:
        return ""
    if kind == "bool":
        return "true" if value else "false"
    if kind == "timestamp" and isinstance(value, datetime):
        return timestamps.format_utc(value)
    if kind == "float":
        return repr(value)
    if kind == "binary":
        return bytes(value).decode("utf-8", "replace")
    return str(value)


_KIND_TYPES = {"int": T.INT, "float": T.FLOAT, "decimal": T.FLOAT, "bool": T.BOOL,
               "string": T.STRING, "binary": T.STRING, "timestamp": T.TIMESTAMP,
               "date": T.TIMESTAMP, "other": T.STRING}


def _infer_text(cells, nulls, ts_parser):
    present = [c.strip() for c in cells if c.strip() != "" and c.strip() not in nulls]
    if not present:
        return T.STRING
    if all(_INT_RE.match(c) for c in present):
        return T.INT
    numeric = [c for c in present if c.lower() != "nan"]
    if numeric and all(_FLOAT_RE.match(c) for c in numeric):
        return T.FLOAT
    if all(c in ("true", "false") for c in present):
        return T.BOOL
    if all(ts_parser.looks_like_timestamp(c) for c in present):
        return T.TIMESTAMP
    return T.STRING


# ---------------------------------------------------------------------------
# Building the dataset


def load(entries):
    """Read every input file (structural checks only)."""
    return [read_file(e) for e in entries]


def build_dataset(tables, ts_parser, nulls, declared=None):
    """A Dataset over all tables.

    declared: name -> type of the schema's physical fields; when None the
    fixed event columns are used and other columns are exposed with
    inferred types.
    """
    if declared is not None:
        types = OrderedDict(declared)
        for table in tables:
            if table.kind == "parquet":
                table.load(set(types), ts_parser)
        plans = {}
    else:
        types = OrderedDict(KNOWN)
        extras = []
        for table in tables:
            for name in table.columns:
                if name not in types and name not in extras:
                    extras.append(name)
        for table in tables:
            if table.kind == "parquet":
                table.load(set(types) | set(extras), ts_parser)
        plans = {}
        for name in extras:
            types[name], plans[name] = _plan_extra(name, tables, nulls, ts_parser)
    converters = {name: _Converter(t, nulls, ts_parser) for name, t in types.items()}
    names = list(types)

    def entries():
        for table in tables:
            absent = [n for n in names if n not in table.columns]
            yield ("absent", table.path, absent)
            if table.kind == "parquet":
                rows = _parquet_rows(table, names, converters, plans)
            else:
                rows = _text_rows(table, names, converters)
            for item in rows:
                yield item

    return Dataset(names, [types[n] for n in names], entries)


def _plan_extra(name, tables, nulls, ts_parser):
    """(type, textual) for an undeclared column; textual means Parquet values go via text."""
    cells = []
    kinds = set()
    for table in tables:
        if name not in table.columns:
            continue
        if table.kind == "parquet":
            kind, _ = table.data[name]
            if kind != "null":
                kinds.add(kind)
        else:
            pos = table.columns.index(name)
            cells.extend(cells_[pos] for _, cells_ in table.rows if pos < len(cells_))
    present = [c for c in cells if c.strip() != "" and c.strip() not in nulls]
    if not present and kinds:
        mapped = {_KIND_TYPES[k] for k in kinds}
        if len(mapped) == 1:
            return mapped.pop(), False
        if mapped == {T.INT, T.FLOAT}:
            return T.FLOAT, False
    for table in tables:
        if table.kind == "parquet" and name in table.data:
            kind, values = table.data[name]
            cells.extend(_canonical_text(kind, v) for v in values if v is not None)
    return _infer_text(cells, nulls, ts_parser), True


def _text_rows(table, names, converters):
    header = table.columns
    width = len(header)
    positions = [(name, header.index(name) if name in header else None) for name in names]
    for ordinal, (line, cells) in enumerate(table.rows, start=1):
        prov = Q.Provenance(table.path, line, ordinal)
        if len(cells) != width:
            if len(cells) < width:
                classification = Q.MISSING_REQUIRED_FIELD
                message = "record has %d fields, expected %d (missing: %s)" % (
                    len(cells), width, ", ".join(header[len(cells):]))
            else:
                classification = Q.PARSE_TYPE_MISMATCH
                message = "record has %d fields, expected %d" % (len(cells), width)
            yield ("bad", Q.BadRecord(prov, classification, message,
                                      {"fields": list(cells), "header": list(header)},
                                      error=InputError))
            continue
        values = {}
        failure = None
        for name, pos in positions:
            if pos is None:
                values[name] = None
                continue
            converter = converters[name]
            try:
                values[name] = converter.text(cells[pos])
            except _CellError as err:
                failure = (name, cells[pos], converter.type, err)
                break
        if failure is None:
            yield ("row", prov, values)
            continue
        name, raw, col_type, err = failure
        yield ("bad", Q.BadRecord(prov, err.classification, "column %r: %s" % (name, err.message),
                                  {"column": name, "value": raw, "expected_type": col_type,
                                   "record": dict(zip(header, cells))}))


def _parquet_rows(table, names, converters, plans):
    columns = []
    for name in names:
        if name in table.data:
            kind, values = table.data[name]
            columns.append((name, kind, values))
        else:
            columns.append((name, None, None))
    for index in range(table.nrows):
        prov = Q.Provenance(table.path, None, index + 1)
        values = {}
        failure = None
        for name, kind, column in columns:
            if column is None:
                values[name] = None
                continue
            raw = column[index]
            converter = converters[name]
            try:
                if plans.get(name):
                    values[name] = (None if raw is None
                                    else converter.text(_canonical_text(kind, raw)))
                else:
                    values[name] = converter.parquet(kind, raw)
            except _CellError as err:
                failure = (name, raw, kind, converter.type, err)
                break
        if failure is None:
            yield ("row", prov, values)
            continue
        name, raw, kind, col_type, err = failure
        record = {n: (c[index] if c is not None else None) for n, _, c in columns}
        yield ("bad", Q.BadRecord(prov, err.classification, "column %r: %s" % (name, err.message),
                                  {"column": name, "value": raw, "parquet_type": kind,
                                   "expected_type": col_type, "record": record}))
"""Input discovery.

Secret: how --input arguments (files, directories, globs) expand to the
effective set of files, which files a directory walk picks up, how the
format of each file is decided from its name, and the canonical order in
which files are processed.
"""

import glob
import os
from collections import namedtuple

from .errors import InputError

CSV = "csv"
TSV = "tsv"
PARQUET = "parquet"
AUTO = "auto"
FORMATS = (CSV, TSV, PARQUET, AUTO)

InputFile = namedtuple("InputFile", "path format gzipped")

_SUFFIXES = (
    (".csv.gz", CSV, True),
    (".tsv.gz", TSV, True),
    (".csv", CSV, False),
    (".tsv", TSV, False),
    (".parquet", PARQUET, False),
)


def detect(name, forced):
    """(format, gzipped) for a file name, or None if it cannot be decided."""
    lowered = name.lower()
    for suffix, fmt, gz in _SUFFIXES:
        if lowered.endswith(suffix):
            return fmt, gz
    if forced in (CSV, TSV, PARQUET):
        return forced, lowered.endswith(".gz")
    return None


def _hidden(name):
    return name.startswith(".")


def _walk(directory, recursive):
    found = []
    if recursive:
        for root, dirs, files in os.walk(directory):
            dirs[:] = sorted(d for d in dirs if not _hidden(d))
            found.extend(os.path.join(root, f) for f in files if not _hidden(f))
    else:
        try:
            names = os.listdir(directory)
        except OSError as exc:
            raise InputError("cannot list directory %r: %s" % (directory, exc.strerror or exc))
        found.extend(os.path.join(directory, n) for n in names if not _hidden(n))
    return [p for p in found if os.path.isfile(p)]


def expand(spec, forced=AUTO, recursive=False):
    """Files named by one path-or-glob, as a dict realpath -> InputFile.

    An explicitly named file must have a recognisable format and a path
    that is neither a file, a directory nor a glob is an error; files
    reached through a directory or a glob are skipped when their format
    cannot be decided.
    """
    chosen = {}

    def add(path, explicit):
        name = os.path.basename(path)
        if not explicit and name.startswith("_") and detect(name, AUTO) is None:
            return  # marker files such as _SUCCESS
        detected = detect(name, forced)
        if detected is None:
            if explicit:
                raise InputError("cannot determine the format of %r (use --format)" % path)
            return
        display = os.path.normpath(path)
        key = os.path.realpath(path)
        current = chosen.get(key)
        if current is None or display < current.path:
            chosen[key] = InputFile(display, detected[0], detected[1])

    if os.path.isdir(spec):
        for path in _walk(spec, recursive):
            add(path, False)
    elif os.path.isfile(spec):
        add(spec, True)
    elif glob.has_magic(spec):
        for match in sorted(glob.glob(spec, recursive=True)):
            if os.path.isdir(match):
                for path in _walk(match, recursive):
                    add(path, False)
            elif os.path.isfile(match):
                add(match, False)
    else:
        raise InputError("input %r does not exist" % spec)
    return chosen


def resolve(specs, recursive=False, forced=AUTO):
    """Expand (path-or-glob, forced_format) pairs into a sorted list of InputFile."""
    chosen = {}
    for spec, override in specs:
        for key, entry in expand(spec, override or forced, recursive).items():
            current = chosen.get(key)
            if current is None or entry.path < current.path:
                chosen[key] = entry
    if not chosen:
        raise InputError("no input files found")
    return sorted(chosen.values(), key=lambda f: f.path)
"""Input table.

Secret: how the column schema and the stream of input rows are stored.
Callers see column names/types and an ordered stream of entries.
"""


class Dataset:
    """Column schema plus a re-iterable stream of entries, in canonical order.

    Each entry is one of
      ("absent", path, names)  -- a file starts; `names` are columns it lacks
      ("row", provenance, values)  -- values: name -> value (None is null)
      ("bad", BadRecord)       -- a row that could not be read
    """

    def __init__(self, names, types, entries):
        self._names = list(names)
        self._types = list(types)
        self._index = {n: i for i, n in enumerate(self._names)}
        self._entries = entries

    def has(self, name):
        return name in self._index

    def type_of(self, name):
        return self._types[self._index[name]]

    @property
    def names(self):
        return tuple(self._names)

    def entries(self):
        return self._entries()

content.content:
"""Multi-source pipelines.

Secret: how configured sources are bound to DSL aliases, how alias-scoped
pre steps run, the static typing of join predicates and projections
(qualified and unqualified column resolution, the working-timestamp rule),
and the join algorithm (hash join on equality conjuncts, temporal bands,
outer-join null padding, deterministic output order).  Callers get a
Dataset of the working relation that the ordinary pipeline consumes.
"""

import re
from collections import OrderedDict
from datetime import timedelta

from . import program as P
from . import quality as Q
from . import valuetypes as T
from .dataset import Dataset
from .declarations import resolve_schema
from .dsl_parser import WORKING_RELATION
from .errors import ConfigError, DslError, ExecutionError, TypeCheckError
from .expressions import coerce, column_references, compile_expression, is_assignable
from .ingest import SourceReader, assign_files

_UNIT_SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
_ROW_FAILURES = (ExecutionError, TypeCheckError, ArithmeticError, ValueError)


def prepare(program, specs, params, ts_parser, log):
    """(dataset, schema_def) of the working relation for engine.execute.

    Everything static (config/DSL consistency, typing of scoped steps, join
    predicates and projections) is checked here; files are only read when
    the dataset is iterated.
    """
    by_name = OrderedDict((spec.name, spec) for spec in specs)
    if program.sources is not None:
        for binding in program.sources:
            if binding.name not in by_name:
                raise ConfigError("pipeline binds source %r, which the ingest config does "
                                  "not define" % binding.name)
    readers = OrderedDict((spec.name, SourceReader(spec, program.schemas, program.schema_name,
                                                   None)) for spec in specs)
    for name, files in assign_files(specs).items():
        readers[name].files = files
    if program.sources is None:
        return _union(program, readers, log)
    return _joined(program, readers, params, ts_parser, log), None


# ---------------------------------------------------------------------------
# Single-relation pipelines over every configured source


def _union(program, readers, log):
    schema = resolve_schema(program)
    if schema is not None:
        types = OrderedDict(schema.physical)
    else:
        types = OrderedDict()
        for reader in readers.values():
            for name, value_type in reader.ensure_columns().items():
                current = types.get(name)
                if current is None or current == value_type:
                    types[name] = value_type
                elif {current, value_type} == {T.INT, T.FLOAT}:
                    types[name] = T.FLOAT
                else:
                    raise TypeCheckError("column %r is %s in one source and %s in another"
                                         % (name, current, value_type))
    plans = []
    for reader in readers.values():
        columns = reader.ensure_columns() if schema is None else reader.columns
        widen = []
        for name, value_type in types.items():
            source_type = columns.get(name)
            if source_type is None or source_type == value_type:
                continue
            if source_type == T.INT and value_type == T.FLOAT:
                widen.append(name)
                continue
            raise TypeCheckError("source %r column %r is %s but the pipeline schema declares %s"
                                 % (reader.spec.name, name, source_type, value_type))
        plans.append((reader, widen))
    names = list(types)

    def entries():
        for reader, widen in plans:
            for prov, values in reader.rows(log):
                row = {n: values.get(n) for n in names}
                for n in widen:
                    if row[n] is not None:
                        row[n] = float(row[n])
                yield ("row", prov, row)

    return Dataset(names, [types[n] for n in names], entries), schema


# ---------------------------------------------------------------------------
# Joined pipelines


class _Relation:
    """Static column types plus a memoised producer of (provenance, values) rows."""

    def __init__(self, columns, produce):
        self.columns = columns
        self._produce = produce
        self._rows = None

    def rows(self):
        if self._rows is None:
            self._rows = self._produce()
        return self._rows


def _joined(program, readers, params, ts_parser, log):
    relations = {}
    for binding in program.sources:
        reader = readers[binding.name]
        blocks = [b for b in program.scoped if b.alias == binding.alias]
        relations[binding.alias] = _scoped_relation(binding.alias, reader, blocks, params, log)
    current = None
    for join in program.joins:
        left = current if join.left == WORKING_RELATION else relations[join.left]
        right = current if join.right == WORKING_RELATION else relations[join.right]
        current = _join_relation(join, left, right, params, ts_parser, log)
        if join.alias is not None:
            relations[join.alias] = current
    final = current
    names = list(final.columns)

    def entries():
        for prov, values in final.rows():
            yield ("row", prov, dict(values))

    return Dataset(names, [final.columns[n] for n in names], entries)


class _Scope:
    """Name resolution for expressions over one aliased relation."""

    def __init__(self, alias, columns):
        self.alias = alias
        self.columns = columns
        self.prefix = alias + "."

    def _column(self, name):
        return name[len(self.prefix):] if name.startswith(self.prefix) else name

    def has(self, name):
        return self._column(name) in self.columns

    def type_of(self, name):
        return self.columns[self._column(name)]


class _ScopedRecord:
    __slots__ = ("data", "prefix")

    def __init__(self, data, prefix):
        self.data = data
        self.prefix = prefix

    def get(self, name):
        if name.startswith(self.prefix):
            name = name[len(self.prefix):]
        return self.data.get(name)


def _scoped_relation(alias, reader, blocks, params, log):
    columns = OrderedDict(reader.ensure_columns())
    scope = _Scope(alias, columns)
    ts_parser = reader.spec.ts_parser
    ops = []

    def unknown(name):
        return TypeCheckError("unknown column %r in with %s { }" % (name, alias))

    for block in blocks:
        for step in block.steps:
            if isinstance(step, P.Calc):
                if step.name in columns:
                    raise DslError("calculated field %r collides with an existing field of %s"
                                   % (step.name, alias))
                compiled = compile_expression(step.expression, scope, params, unknown=unknown,
                                              ts_parser=ts_parser)
                if not is_assignable(step.type, compiled.type):
                    raise TypeCheckError("calc %r is declared %s but its expression is %s"
                                         % (step.name, step.type, compiled.type))
                columns[step.name] = step.type
                ops.append(("derive", step.name, coerce(step.type, compiled)))
            elif isinstance(step, P.Filter):
                compiled = compile_expression(step.predicate, scope, params, unknown=unknown,
                                              ts_parser=ts_parser)
                if not T.is_bool(compiled.type):
                    raise TypeCheckError("filter expression must be boolean, got %s"
                                         % compiled.type)
                ops.append(("filter", None, compiled.evaluate))
            else:
                compiled = compile_expression(step.expression, scope, params, unknown=unknown,
                                              ts_parser=ts_parser)
                columns[step.column] = compiled.type
                ops.append(("derive", step.column, compiled.evaluate))

    def produce():
        rows = []
        prefix = alias + "."
        for prov, values in reader.rows(log):
            data = OrderedDict(values)
            record = _ScopedRecord(data, prefix)
            try:
                keep = True
                for kind, name, evaluate in ops:
                    if kind == "filter":
                        if evaluate(record) is not True:
                            keep = False
                            break
                    else:
                        data[name] = evaluate(record)
            except _ROW_FAILURES as exc:
                log.add(Q.BadRecord(prov, _classify(exc), str(exc), {"values": data}))
                continue
            if keep:
                rows.append((prov, data))
        return rows

    return _Relation(columns, produce)


def _classify(exc):
    return Q.TYPE_ERROR if isinstance(exc, TypeCheckError) else Q.RUNTIME_ERROR


class _PairScope:
    """Name resolution over a pair of relations: `L.col`, `R.col` or an unambiguous `col`."""

    def __init__(self, left_name, left, right_name, right):
        self.sides = (left, right)
        self.qualifiers = (left_name, right_name)
        self.resolve = {}
        for side, (name, columns) in enumerate(((left_name, left), (right_name, right))):
            for column in columns:
                self.resolve["%s.%s" % (name, column)] = (side, column)
        self.ambiguous = set(left).intersection(right)
        for side, (columns, other) in enumerate(((left, right), (right, left))):
            for column in columns:
                if column not in other:
                    self.resolve[column] = (side, column)

    def has(self, name):
        return name in self.resolve

    def type_of(self, name):
        side, column = self.resolve[name]
        return self.sides[side][column]

    def unknown(self, name):
        if name in self.ambiguous:
            return DslError("column %r exists on both sides of the join; qualify it as %s.%s or "
                            "%s.%s" % (name, self.qualifiers[0], name, self.qualifiers[1], name))
        if "." in name:
            qualifier = name.split(".", 1)[0]
            if qualifier not in self.qualifiers:
                return DslError("%r does not name a side of this join (expected %s or %s)"
                                % (qualifier, self.qualifiers[0], self.qualifiers[1]))
        return TypeCheckError("unknown column %r in join" % name)

    def sides_of(self, expr):
        return {self.resolve[n][0] for n in column_references(expr) if n in self.resolve}


class _PairRecord:
    __slots__ = ("left", "right", "resolve")

    def __init__(self, left, right, resolve):
        self.left = left
        self.right = right
        self.resolve = resolve

    def get(self, name):
        side, column = self.resolve[name]
        data = self.left if side == 0 else self.right
        return None if data is None else data.get(column)


def _conjuncts(expr):
    if isinstance(expr, P.Binary) and expr.op == "&":
        return _conjuncts(expr.left) + _conjuncts(expr.right)
    return [expr]


def _band(join, left, right, params):
    spec = join.within
    for side, relation in zip((join.left, join.right), (left, right)):
        if "timestamp" not in relation.columns:
            raise DslError("line %d: join within %s requires a timestamp on both sides, but %r "
                           "has none" % (join.line, _describe(spec), side))
        if not T.is_timestamp(relation.columns["timestamp"]):
            raise TypeCheckError("join within requires %r.timestamp to be a timestamp, got %s"
                                 % (side, relation.columns["timestamp"]))
    if spec.param is None:
        return timedelta(seconds=spec.amount * _UNIT_SECONDS[spec.unit])
    if spec.param not in params:
        raise DslError("unknown parameter %r" % spec.param)
    value_type, value = params[spec.param]
    m = re.match(r"^\s*(\d+)\s*([smhd])\s*$", value) if T.is_string(value_type) else None
    if not m:
        raise TypeCheckError("within parameter %r must be a duration like '10m', got %r"
                             % (spec.param, value))
    return timedelta(seconds=int(m.group(1)) * _UNIT_SECONDS[m.group(2)])


def _describe(spec):
    if spec.param is not None:
        return "param(%r)" % spec.param
    return "%d%s" % (spec.amount, spec.unit)


def _join_relation(join, left, right, params, ts_parser, log):
    scope = _PairScope(join.left, left.columns, join.right, right.columns)

    def compile_pair(expr):
        return compile_expression(expr, scope, params, unknown=scope.unknown,
                                  ts_parser=ts_parser)

    on = compile_pair(join.on)
    if not T.is_bool(on.type):
        raise TypeCheckError("join on predicate must be boolean, got %s" % on.type)
    band = _band(join, left, right, params) if join.within is not None else None

    keys = []
    for conjunct in _conjuncts(join.on):
        if not (isinstance(conjunct, P.Binary) and conjunct.op == "=="):
            continue
        a, b = scope.sides_of(conjunct.left), scope.sides_of(conjunct.right)
        if a == {0} and b == {1}:
            keys.append((compile_pair(conjunct.left).evaluate,
                         compile_pair(conjunct.right).evaluate))
        elif a == {1} and b == {0}:
            keys.append((compile_pair(conjunct.right).evaluate,
                         compile_pair(conjunct.left).evaluate))

    columns = OrderedDict()
    project = []
    for item in join.project:
        compiled = compile_pair(item.expression)
        columns[item.name] = compiled.type
        project.append((item.name, compiled.evaluate))
    if "timestamp" in columns:
        if not T.is_timestamp(columns["timestamp"]):
            raise TypeCheckError("projected timestamp must be a timestamp, got %s"
                                 % columns["timestamp"])
    else:
        lt, rt = left.columns.get("timestamp"), right.columns.get("timestamp")
        if lt is not None and rt is not None:
            raise TypeCheckError("line %d: both %r and %r have a timestamp; project must say "
                                 "which one is the working timestamp" % (join.line, join.left,
                                                                         join.right))
        if lt is None:
            raise TypeCheckError("line %d: project defines no timestamp and %r has none to "
                                 "default to" % (join.line, join.left))
        if not T.is_timestamp(lt):
            raise TypeCheckError("%r.timestamp is %s, not a timestamp" % (join.left, lt))
        columns["timestamp"] = lt
        project.append(("timestamp", compile_pair(
            P.ColumnRef("%s.timestamp" % join.left)).evaluate))

    resolve = scope.resolve
    kind = join.kind

    def produce():
        lrows, rrows = left.rows(), right.rows()
        out = []

        def emit(prov, l, r):
            record = _PairRecord(l, r, resolve)
            values = OrderedDict()
            try:
                for name, evaluate in project:
                    values[name] = evaluate(record)
            except _ROW_FAILURES as exc:
                log.add(Q.BadRecord(prov, _classify(exc), "join projection: %s" % exc,
                                    {"left": l, "right": r}))
                return
            out.append((prov, values))

        index = None
        if keys:
            index = {}
            for j, (_, r) in enumerate(rrows):
                key = _key(keys, 1, _PairRecord(None, r, resolve))
                if key is not None:
                    index.setdefault(key, []).append(j)
        matched = [False] * len(rrows)
        for prov, l in lrows:
            if index is not None:
                key = _key(keys, 0, _PairRecord(l, None, resolve))
                candidates = index.get(key, ()) if key is not None else ()
            else:
                candidates = range(len(rrows))
            found = False
            for j in candidates:
                rprov, r = rrows[j]
                if band is not None and not _within(l, r, band):
                    continue
                try:
                    hit = on.evaluate(_PairRecord(l, r, resolve)) is True
                except _ROW_FAILURES as exc:
                    log.add(Q.BadRecord(prov, _classify(exc), "join predicate: %s" % exc,
                                        {"left": l, "right": r}))
                    continue
                if hit:
                    found = True
                    matched[j] = True
                    emit(prov, l, r)
            if not found and kind in ("left", "full"):
                emit(prov, l, None)
        if kind in ("right", "full"):
            for j, (rprov, r) in enumerate(rrows):
                if not matched[j]:
                    emit(rprov, None, r)
        return out

    return _Relation(columns, produce)


def _key(keys, side, record):
    values = []
    for pair in keys:
        try:
            value = pair[side](record)
        except _ROW_FAILURES:
            return None
        if value is None:
            return None
        values.append(value)
    return tuple(values)


def _within(l, r, band):
    a, b = l.get("timestamp"), r.get("timestamp")
    if a is None or b is None:
        return False
    return abs(a - b) <= band
"""Data-quality bookkeeping.

Secret: how rejected rows are classified, which failure category a bad
record maps to in strict mode, and the JSON Lines shape and ordering of the
bad-records report.
"""

import json
import math
from datetime import datetime

from .errors import ExecutionError, InputError, TypeCheckError

PARSE_TYPE_MISMATCH = "PARSE_TYPE_MISMATCH"
TIMESTAMP_PARSE_ERROR = "TIMESTAMP_PARSE_ERROR"
RUNTIME_ERROR = "RUNTIME_ERROR"
TYPE_ERROR = "TYPE_ERROR"
MISSING_REQUIRED_FIELD = "MISSING_REQUIRED_FIELD"
PARQUET_TYPE_MISMATCH = "PARQUET_TYPE_MISMATCH"

_STRICT_ERRORS = {
    PARSE_TYPE_MISMATCH: TypeCheckError,
    TIMESTAMP_PARSE_ERROR: TypeCheckError,
    RUNTIME_ERROR: ExecutionError,
    TYPE_ERROR: TypeCheckError,
    MISSING_REQUIRED_FIELD: TypeCheckError,
    PARQUET_TYPE_MISMATCH: TypeCheckError,
}


class Provenance:
    """Where a row came from: file path, physical line (None for Parquet), row ordinal."""

    __slots__ = ("file", "line", "row")

    def __init__(self, file, line, row):
        self.file = file
        self.line = line
        self.row = row

    def describe(self):
        if self.line is not None:
            return "%s:%d" % (self.file, self.line)
        if self.row is not None:
            return "%s: row %d" % (self.file, self.row)
        return self.file


class BadRecord:
    """One rejected row.

    error: optional MtlError class raised for it in strict mode (defaults by
    classification).
    """

    def __init__(self, provenance, classification, message, context=None, error=None):
        self.provenance = provenance
        self.classification = classification
        self.message = message
        self.context = context or {}
        self.error = error or _STRICT_ERRORS[classification]

    def sort_key(self):
        p = self.provenance
        line = p.line if p.line is not None else -1
        return (p.file, line, p.row if p.row is not None else -1)

    def as_json(self):
        p = self.provenance
        obj = {
            "file": p.file,
            "line": p.line,
            "row": p.row,
            "error": self.classification,
            "message": self.message,
            "context": _json_safe(self.context),
        }
        return json.dumps(obj, sort_keys=True, ensure_ascii=False, allow_nan=False)


def _json_safe(value):
    if value is None or isinstance(value, (bool, int, str)):
        return value
    if isinstance(value, float):
        return value if math.isfinite(value) else repr(value)
    if isinstance(value, dict):
        return {str(k): _json_safe(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe(v) for v in value]
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    return str(value)


class BadRecordLog:
    """Collects bad records; in strict mode the first one aborts the run."""

    def __init__(self, strict):
        self.strict = strict
        self.records = []

    def add(self, record):
        self.records.append(record)
        if self.strict:
            raise record.error("%s: %s: %s" % (record.provenance.describe(),
                                               record.classification, record.message))

    def write(self, path):
        """Write the JSON Lines report; nothing is created when there are no bad rows."""
        if not path or not self.records:
            return
        ordered = sorted(self.records, key=BadRecord.sort_key)
        text = "".join(r.as_json() + "\n" for r in ordered)
        try:
            with open(path, "wb") as handle:
                handle.write(text.encode("utf-8"))
        except OSError as exc:
            raise InputError("cannot write bad records %r: %s" % (path, exc.strerror or exc))
"""JSON rendering.

Secret: the JSON document shape, object key ordering and how
values (numbers, timestamps, nulls) are encoded.
"""

import json
import math
from collections import OrderedDict

from . import timestamps
from . import valuetypes as T
from .errors import ExecutionError


def _encode(value, value_type=None):
    if value is None:
        return None
    if value_type is not None and T.is_timestamp(value_type):
        return timestamps.format_utc(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ExecutionError("cannot emit non-finite number")
        return value + 0.0
    return value


def _object(result, row):
    obj = OrderedDict()
    if result.windowed:
        obj["window_start"] = timestamps.format_utc(row.window_start)
        obj["window_end"] = timestamps.format_utc(row.window_end)
    for name, value_type, value in zip(result.group_columns, result.group_types, row.keys):
        obj[name] = _encode(value, value_type)
    for alias in sorted(result.aliases):
        obj[alias] = _encode(row.values[alias])
    for name, value_type in sorted(zip(result.calc_names, result.calc_types)):
        obj[name] = _encode(row.values[name], value_type)
    return obj


def render(result):
    """Serialise a ResultSet to the deterministic JSON text."""
    if result.scalar:
        document = _object(result, result.rows[0])
    else:
        document = [_object(result, r) for r in result.rows]
    try:
        return json.dumps(document, indent=2, ensure_ascii=False, allow_nan=False) + "\n"
    except ValueError as exc:
        raise ExecutionError("cannot emit result: %s" % exc)

