input.command:
cd /tmp/t5 && P=/workspace/.venv/bin/python; M=/workspace/mtl.py
cat > j2.mtl <<'EOF'
mtl_version 1.5
pipeline J2 {
  params { tol: string = "30m" }
  sources { web as W, pos as P }
  with W { calc p2 = score(price, 0) : float }
  join W with P on (W.item == P.item & W.location == P.location & W.price < 100) within param("tol") type left project {
    W.timestamp as timestamp, up(W.location) as loc, W.p2 as p2, P.stock as stock
  }
  group_by(loc)
  aggregate sum(p2) as s, count(stock) as matched
}
EOF
cat > u9.py <<'EOF'
@udf("float", "float", returns="float")
def score(a, b): return a + b
@udf
def up(s: str) -> str: return s.upper()
EOF
$P $M --dsl j2.mtl --ingest-config ingest.yml --udf u9.py --meta-out j2.meta.json; echo "exit=$?"
$P -c "import json; d=json.load(open('j2.meta.json')); print(d['pipeline']['joins'], [u['name'] for u in d['udfs']])"

